    # Ruuvi tag). Works for any picker: Discovery view passes a discovery_id
    # or MAC; Bluetooth view passes a MAC. Persisted in HA's local storage.
    if not hass.services.has_service(DOMAIN, "ignore_device"):
        async def handle_ignore_device(call: ServiceCall) -> None:
            from . import ble_ignore
            device_id = str(call.data["id"]).upper()
            rt = hass.data.get(DOMAIN, {}).get(entry.entry_id, {})
            state = rt.get("ignore_state")
            if state is None:
                return
            ble_ignore.add_manual(state, device_id)
            await _async_apply_ignore_change(hass, entry)

        hass.services.async_register(
            DOMAIN,
            "ignore_device",
            handle_ignore_device,
            schema=vol.Schema({vol.Required("id"): str}),
        )

