        async def handle_restore_device(call: ServiceCall) -> None:
            from . import ble_ignore
            device_id = str(call.data["id"]).upper()
            rt = hass.data.get(DOMAIN, {}).get(entry.entry_id, {})
            state = rt.get("ignore_state")
            if state is None:
                return
            # Full restore — drops a manual ignore AND any Cerbo ownership, so an
            # explicit un-ignore sticks even while the Cerbo is still present.
            ble_ignore.remove(state, device_id)
            await _async_apply_ignore_change(hass, entry)

