        from .dashboard import async_refresh_stock_images
        client = _first_client()
        uploaded: list[dict[str, Any]] = []
        if client is not None:
            try:
                result = await client.async_get_uploads_list()
                uploaded = (result or {}).get("images") or []
            except (ConnectionError, TimeoutError):
                uploaded = []  # best-effort — still return the stock set
        # Rescan rather than read the setup-primed cache: the add-on refreshes
        # /config/www/sensa on its own restart, so a default shipped in a new
        # build would otherwise not be offered until HA itself restarted.
        stock = await async_refresh_stock_images(hass)
        connection.send_result(msg["id"], {
            "stock": [dict(o) for o in stock],
            "uploaded": uploaded,
        })

