    @websocket_api.websocket_command({
        vol.Required("type"): "sensa_nomad/upload_image",
        vol.Required("filename"): str,
        vol.Required("content_type"): str,
        vol.Required("data_b64"): str,
        vol.Optional("name"): str,
    })
    @websocket_api.async_response
    async def _ws_upload_image(hass, connection, msg):
        client = _first_client()
        if client is None:
            connection.send_error(
                msg["id"], "not_ready",
                "Sensa App client not ready — try again in a moment",
            )
            return
        try:
            result = await client.async_post_upload_image(
                filename=msg["filename"],
                content_type=msg["content_type"],
                data_b64=msg["data_b64"],
                name=msg.get("name"),
            )
        except (ConnectionError, TimeoutError) as exc:
            connection.send_error(msg["id"], "addon_unreachable", str(exc))
            return
        if not isinstance(result, dict) or not result.get("url"):
            message = (result or {}).get("message") or (result or {}).get("error") or "upload failed"
            connection.send_error(msg["id"], "upload_failed", str(message))
            return
        connection.send_result(msg["id"], result)

    websocket_api.async_register_command(hass, _ws_upload_image)

