    # Sensa log WS commands — each Log card reads recent entries and clears the
    # log. Both read/write the in-memory ring buffers (see _log.py), so a plain
    # @callback (no executor) is enough.
    #
    # `source` names WHICH log (Intelligence → Log = vehicle, Settings → System
    # Log = system) and is filtered server-side, before `limit`, so a page of
    # one log is never eaten by traffic on the other. It is OPTIONAL and means
    # "everything" when absent: this is the raw store read, and a REQUIRED field
    # would make voluptuous reject a browser holding a stale card bundle
    # outright, blanking the tab. Degrading to extra rows beats a blank tab.
    @websocket_api.websocket_command({
        vol.Required("type"): "sensa_nomad/get_log",
        vol.Optional("limit"): int,
        vol.Optional("source"): vol.In(SENSA_LOG_SOURCES),
        # One device's lines only (the heater diagnostics fault history).
        vol.Optional("device_id"): str,
    })
    @callback
    def _ws_get_log(hass, connection, msg):
        from ._log import get_sensa_log
        entries = get_sensa_log(
            hass, msg.get("limit"), msg.get("source"), msg.get("device_id"),
        )
        connection.send_result(msg["id"], {"entries": entries})

    websocket_api.async_register_command(hass, _ws_get_log)

    # One heater's extended diagnostics, decoded (the heater card's Nerd Mode
    # Diagnostics popup and the service report). Read-only; the decode and
    # the fault wording live in heater_diagnostics / autoterm_diag, so every
    # consumer shows the same thing.
    @websocket_api.websocket_command({
        vol.Required("type"): "sensa_nomad/heater_diagnostics",
        vol.Required("device_id"): str,
    })
    @callback
    def _ws_heater_diagnostics(hass, connection, msg):
        from .heater_diagnostics import diagnostics_for, heater_rows

        for cfg_entry in hass.config_entries.async_entries(DOMAIN):
            for row in heater_rows(hass, cfg_entry):
                if str(row.get("device_id") or "") == msg["device_id"]:
                    connection.send_result(
                        msg["id"], diagnostics_for(hass, cfg_entry, row),
                    )
                    return
        connection.send_result(
            msg["id"], {"device_id": msg["device_id"], "status": "not_found"},
        )

    websocket_api.async_register_command(hass, _ws_heater_diagnostics)

