    # SensaClimate's Diesel cost chart: each heater's cost per day
    # (`diesel_use.cost_history`), from the diesel ledger and the day's price.
    @websocket_api.websocket_command({
        vol.Required("type"): "sensa_nomad/diesel_cost_history",
        vol.Optional("days", default=30): vol.All(int, vol.Range(min=1, max=90)),
    })
    @callback
    def _ws_diesel_cost_history(hass, connection, msg):
        from homeassistant.util import dt as dt_util

