    # Read-only diagnostics for one compose container (image, created, restart
    # count, MOUNTS, last 200 log lines), for the Containers panel's Details
    # expander. STAFF-ONLY: `user_is_sensa_staff`, never `can_admin` -- on DIY
    # the HA admin is the customer, and a container log is Sensa's to read, not
    # theirs. Built 2026-09-07 after a night unable to tell, from inside HA,
    # which configuration file a fielded Zigbee2MQTT was actually running with.
    @websocket_api.websocket_command({
        vol.Required("type"): "sensa_nomad/container_inspect",
        vol.Required("service"): str,
    })
    @websocket_api.async_response
    async def _ws_container_inspect(hass, connection, msg):
        from .appliance import user_is_sensa_staff

        if not user_is_sensa_staff(hass, connection.user):
            connection.send_error(msg["id"], "unauthorized", "Sensa support only.")
            return
        service = str(msg.get("service") or "").strip()
        if not _CONTAINER_SLUG_RE.match(service):
            connection.send_error(
                msg["id"], "invalid_format", _CONTAINER_INSPECT_ERROR_TEXT["invalid_service"]
            )
            return
        client = _first_client()
        if client is None:
            connection.send_error(msg["id"], "unavailable", "The Sensa App is not reachable.")
            return
        try:
            result = await client.async_get_container_inspect(service=service)
        except (ConnectionError, TimeoutError) as err:
            connection.send_error(
                msg["id"], "unavailable", f"The Sensa App did not answer: {err}"
            )
            return
        error = str((result or {}).get("error") or "")
        if error:
            connection.send_error(
                msg["id"], error,
                _CONTAINER_INSPECT_ERROR_TEXT.get(error, "The container could not be inspected."),
            )
            return
        connection.send_result(msg["id"], result)

    websocket_api.async_register_command(hass, _ws_container_inspect)

    # Mode Editor "Defaults" button: compute the recommended per-mode
