async def _async_add_relay_platform_entities(
    hass: HomeAssistant, entry: ConfigEntry, device: dict[str, Any],
) -> None:
    """Create the 8 channel-name text + 8 channel-enabled switch entities
    for one Sensa relay controller, and on first add put the device into
    a known-safe state (all channels disabled, all physical outputs off).

    Relay devices added via the Discovery picker after initial setup don't
    flow through text.py / switch.py async_setup_entry (which only iterates
    coordinator.data captured at setup time), so without this dynamic path
    the dashboard YAML references entity_ids that never get registered and
    every channel renders as "entity not found".

    Mirrors `_async_add_teltonika_platform_entities`: uses the
    `vendor_add_text` / `vendor_add_switches` callbacks each platform
    stashes in runtime on setup, guarded by a per-device flag so repeated
    add attempts don't double-register.
    """
    from .select import build_relay_assignment_selects
    from .switch import build_relay_enabled_switches
    from .text import build_relay_text_entities

    device_id = str(device.get("device_id") or device.get("id") or "")
    if not device_id:
        return

    # First-add safety defaults: all 8 channels disabled + every physical
    # output forced off. Idempotent across reloads via the persistent
    # `relay_initialized` list under entry.options. Runs before the
    # platform-callback guard so the defaults still land if the entity
    # creation step has to defer to a later reload.
    is_first_add = _apply_relay_first_add_defaults(hass, entry, device_id, device)
    if is_first_add:
        hass.async_create_task(
            _async_force_relay_outputs_off(hass, entry, device)
        )

    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    guard = f"relay_platform_entities_{device_id}"
    if runtime.get(guard):
        return

    # Registry-existence check. switch.py / text.py also create these
    # entities during platform setup (the safety-net path). On HA
    # restart / integration reload the registry already holds the
    # unique_ids before this dynamic-path call fires; re-registering
    # would log "Platform sensa_nomad does not generate unique IDs"
    # warnings on every startup. Mirror the same guard the Teltonika
    # dynamic-add uses (`_async_start_teltonika`).
    try:
        from homeassistant.helpers.entity_registry import (
            async_get as async_get_entity_registry,
        )
        ent_reg = async_get_entity_registry(hass)
        existing = any(
            e.unique_id.startswith(f"{entry.entry_id}_{device_id}_relay_")
            for e in ent_reg.entities.values()
            if e.config_entry_id == entry.entry_id
        )
    except Exception:  # noqa: BLE001
        existing = False
    if existing:
        runtime[guard] = True
        _LOGGER.debug(
            "Relay platform entities already in registry for %s — skipping re-add",
            device_id,
        )
        return

    add_text = runtime.get("vendor_add_text")
    add_switches = runtime.get("vendor_add_switches")
    add_selects = runtime.get("vendor_add_selects")
    if not add_text or not add_switches:
        _LOGGER.debug(
            "Relay platform add callbacks not present for %s "
            "(add_text=%s, add_switches=%s) — entities will appear "
            "on next regen",
            device_id, bool(add_text), bool(add_switches),
        )
        return

    try:
        add_text(build_relay_text_entities(hass, entry, device))
        add_switches(build_relay_enabled_switches(hass, entry, device))
        # "Works with" selects — best-effort: a missing select callback
        # mustn't block the text/switch adds the dashboard card depends on.
        if add_selects:
            add_selects(build_relay_assignment_selects(hass, entry, device))
        runtime[guard] = True
        _LOGGER.info(
            "Added relay platform entities for %s "
            "(8 channel names + 8 enabled switches + 8 works-with selects "
            "+ 1 device-name)",
            device_id,
        )
    except Exception:
        _LOGGER.warning(
            "Failed to add relay platform entities for %s",
            device_id, exc_info=True,
        )


def _migrate_home_layout_options(
    hass: HomeAssistant, entry: ConfigEntry,
) -> None:
    """One-time migration from the legacy boolean "Show on Home Layout" switch
    ledgers to the HABITATION column placement ledger.

    Any device previously ticked ON is placed in the "right" column of the
    Habitation home — its historic placement (heaters/AC/lights all lived in the
    right column on Power Central). The Cab ledger starts empty (the legacy
    toggle only ever affected the Habitation home). Runs only when the
    Habitation placement key is ABSENT, so it fires exactly once; it also drops
    the now-dead legacy keys.
    """
    from .const import HOME_LAYOUT_LEGACY_OPTIONS, HOME_LAYOUT_SURFACES

    hab_option = HOME_LAYOUT_SURFACES[0]["option"]
    options = getattr(entry, "options", None) or {}
    if hab_option in options:
        return
    placement: dict[str, str] = {}
    for key in HOME_LAYOUT_LEGACY_OPTIONS:
        for device_id in (options.get(key) or []):
            if device_id:
                placement.setdefault(str(device_id), "right")
    updated = {
        k: v for k, v in options.items() if k not in HOME_LAYOUT_LEGACY_OPTIONS
    }
    updated[hab_option] = placement
    hass.config_entries.async_update_entry(entry, options=updated)
    if placement:
        _LOGGER.info(
            "Migrated %d device(s) from the legacy Show-on-Home toggle to the "
            "Habitation Home Layout placement ledger (right column)",
            len(placement),
        )


def _cleanup_legacy_home_layout_switches(
    hass: HomeAssistant, entry: ConfigEntry,
) -> None:
    """Reap lingering legacy "Show on Home Layout" SWITCH entities.

    The control is now a select, so the switch platform never re-creates these;
    a restored (unavailable) switch would otherwise sit in the registry forever.
    """
    from .const import HOME_LAYOUT_LEGACY_SWITCH_SUFFIXES

    try:
        from homeassistant.helpers import entity_registry as er
        ent_reg = er.async_get(hass)
        prefix = f"{entry.entry_id}_"
        for ent in list(ent_reg.entities.values()):
            if ent.config_entry_id != entry.entry_id or ent.domain != "switch":
                continue
            uid = ent.unique_id or ""
            if uid.startswith(prefix) and any(
                uid.endswith(s) for s in HOME_LAYOUT_LEGACY_SWITCH_SUFFIXES
            ):
                ent_reg.async_remove(ent.entity_id)
    except Exception:
        _LOGGER.debug("legacy home-layout switch cleanup raised", exc_info=True)


def _stamp_home_layout_flags(
    devices: list[dict[str, Any]], entry: ConfigEntry,
) -> None:
    """Stamp each eligible device's `home_placement` column onto its dict IN
    PLACE — the Home-tab column the customer picked in its "Home Layout" select
    ("left"/"middle"/"right"), or None (Off, the default).

    Options-as-truth: `entry.options["home_layout_placement"]` maps a device id
    to its column, read by the dashboard's `_home_placement_columns`. Covers
    every eligible service class in `HOME_LAYOUT_KINDS` — heaters, lights, AC.

    MUST run on BOTH the initial-setup build AND every rebuild — omitting it
    from setup drops a placed device off Home after a plain restart. Call it
    right after `_attach_service_class_rows` so `service_class` is populated.
    Stamps a per-surface dict, e.g. ``{"hab": "right", "cab": None}``, plus the
    matching `home_order` dict (`{"hab": 1, "cab": 3}`) — the sort order WITHIN
    that column. Both are stamped here together so they cannot come from
    different places and disagree.
    """
    from .const import (
        HOME_LAYOUT_KINDS,
        HOME_LAYOUT_SURFACES,
        home_layout_order_for,
    )

    eligible = {cls for kind in HOME_LAYOUT_KINDS for cls in kind["classes"]}
    ledgers = {
        surface["key"]: (entry.options.get(surface["option"]) or {})
        for surface in HOME_LAYOUT_SURFACES
    }
    for dev in devices:
        if dev.get("service_class") not in eligible:
            continue
        did = str(dev.get("device_id") or dev.get("id") or "")
        dev["home_placement"] = {
            surface["key"]: (ledgers[surface["key"]].get(did) if did else None)
            for surface in HOME_LAYOUT_SURFACES
        }
        dev["home_order"] = {
            surface["key"]: home_layout_order_for(entry.options, surface, did)
            for surface in HOME_LAYOUT_SURFACES
        }


def _prune_home_layout_options(
    hass: HomeAssistant, entry: ConfigEntry, removed_device_ids: set[str],
) -> None:
    """Drop removed devices from every surface's placement ledger (and any
    legacy switch ledgers) so a stale entry can't resurface the device on Home
    when its id is re-added."""
    from .const import HOME_LAYOUT_LEGACY_OPTIONS, HOME_LAYOUT_SURFACES

    options = getattr(entry, "options", None) or {}
    updated = dict(options)
    changed = False
    for surface in HOME_LAYOUT_SURFACES:
        # Both ledgers for each surface: the placement column AND the sort
        # order. Pruning only the placement would leave an orphan order that
        # silently reapplied if the same device id came back.
        for option_key in (surface["option"], surface["order_option"]):
            ledger = options.get(option_key)
            if isinstance(ledger, dict):
                kept = {
                    d: c for d, c in ledger.items()
                    if d not in removed_device_ids
                }
                if kept != ledger:
                    updated[option_key] = kept
                    changed = True
    for key in HOME_LAYOUT_LEGACY_OPTIONS:
        current = list(options.get(key) or [])
        kept_list = [d for d in current if d not in removed_device_ids]
        if kept_list != current:
            updated[key] = kept_list
            changed = True
    if changed:
        hass.config_entries.async_update_entry(entry, options=updated)


def _remove_home_layout_entities(
    hass: HomeAssistant, entry: ConfigEntry, removed_device_ids: set[str],
) -> None:
    """Delete a removed device's per-surface "Home Layout" placement selects
    (and any legacy Show-on-Home switch), or the registry backstop in select.py
    would keep re-creating the selects."""
    from .const import HOME_LAYOUT_LEGACY_SWITCH_SUFFIXES, HOME_LAYOUT_SURFACES
    try:
        from homeassistant.helpers import entity_registry as er
        ent_reg = er.async_get(hass)
        for device_id in removed_device_ids:
            for surface in HOME_LAYOUT_SURFACES:
                uid = f"{entry.entry_id}_{device_id}{surface['uid_suffix']}"
                eid = ent_reg.async_get_entity_id("select", DOMAIN, uid)
                if eid:
                    ent_reg.async_remove(eid)
                # The sort-order NUMBER has its own registry backstop in
                # number.py, so it needs reaping here too or it would be
                # re-created for a device that no longer exists.
                ouid = (
                    f"{entry.entry_id}_{device_id}{surface['order_uid_suffix']}"
                )
                oeid = ent_reg.async_get_entity_id("number", DOMAIN, ouid)
                if oeid:
                    ent_reg.async_remove(oeid)
            for suffix in HOME_LAYOUT_LEGACY_SWITCH_SUFFIXES:
                luid = f"{entry.entry_id}_{device_id}{suffix}"
                leid = ent_reg.async_get_entity_id("switch", DOMAIN, luid)
                if leid:
                    ent_reg.async_remove(leid)
    except Exception:
        _LOGGER.debug("home-layout entity orphan sweep raised", exc_info=True)


def _remove_header_power_chip_entities(
    hass: HomeAssistant, entry: ConfigEntry, removed_device_ids: set[str],
) -> None:
    """Drop a removed device from the header power-chip ledger and delete its
    toggle entity.

    Both halves matter: the ledger is one of the switch's three build sources,
    so pruning the entity alone would see it re-created on the next setup, and
    a stale ON id would put the chip straight back in the header if the same
    device_id is ever re-added.
    """
    from .const import HEADER_POWER_CHIP_OPTION, HEADER_POWER_CHIP_UID_SUFFIX

    options = getattr(entry, "options", None) or {}
    current = list(options.get(HEADER_POWER_CHIP_OPTION) or [])
    kept = [str(d) for d in current if str(d) not in removed_device_ids]
    if kept != current:
        hass.config_entries.async_update_entry(
            entry,
            options={**options, HEADER_POWER_CHIP_OPTION: kept},
        )
    try:
        from homeassistant.helpers import entity_registry as er

        ent_reg = er.async_get(hass)
        for device_id in removed_device_ids:
            uid = f"{entry.entry_id}_{device_id}{HEADER_POWER_CHIP_UID_SUFFIX}"
            eid = ent_reg.async_get_entity_id("switch", DOMAIN, uid)
            if eid:
                ent_reg.async_remove(eid)
    except Exception:
        _LOGGER.debug(
            "header power-chip entity orphan sweep raised", exc_info=True,
        )


async def async_heal_zigbee_record_class(
    hass: HomeAssistant,
    entry: ConfigEntry,
    device: dict[str, Any],
    service_class: str,
) -> bool:
    """Write a live-resolved class onto a Zigbee2MQTT record that has none.

    The Discovery sensor calls this for a registered Z2M device whose backend
    record classifies to nothing while the live row (Z2M's identification,
    catalog-authoritative) resolves a class. Such a record is invisible to every
    surface that reads records rather than rows: no Lighting card, no Home
    Layout dropdowns, none of the row's options, though the row itself shows a
    green dot and the right photo. Found on a customer box 2026-09-08 on two
    GL-SPI-206P. Nobody can see why from the outside, so the integration puts
    the class back itself and rebuilds what depends on it.

    Once per device per boot: a write the App refuses must not be retried every
    30 s poll. Returns True when the record was updated.
    """
    from homeassistant.helpers.dispatcher import async_dispatcher_send

    from ._log import sensa_log
    from .const import SIGNAL_DASHBOARD_REGEN_REQUESTED

    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id)
    if not runtime:
        return False
    device_id = str(device.get("device_id") or "")
    if not device_id or not service_class:
        return False
    healed: set[str] = runtime.setdefault("zigbee_record_class_healed", set())
    if device_id in healed:
        return False
    healed.add(device_id)
    client = runtime.get("client")
    if client is None:
        return False
    name = device.get("display_name") or device.get("name") or device_id
    try:
        result = await client.async_update_device(
            device_id=device_id, role=service_class,
        )
    except Exception as err:  # noqa: BLE001 - a heal must never take the poll down
        _LOGGER.warning(
            "Zigbee record heal: could not write class %s onto %s (%s): %s",
            service_class, name, device_id, err,
        )
        return False
    if isinstance(result, dict) and result.get("error"):
        # A 4xx comes back as its body, not an exception (api/client.py).
        _LOGGER.warning(
            "Zigbee record heal: App refused class %s for %s (%s): %s",
            service_class, name, device_id, result,
        )
        return False
    _LOGGER.warning(
        "Zigbee record heal: %s (%s) was stored with no device class; "
        "wrote %s from its live Zigbee2MQTT identification",
        name, device_id, service_class,
    )
    sensa_log(
        hass,
        "info",
        f"Repaired {name}: it had been saved without a device type, so it was "
        f"missing from its tab and had no options. Restored as {service_class}.",
        source=SENSA_LOG_SOURCE_SYSTEM,
    )
    coordinator = runtime.get("coordinator")
    if coordinator is not None:
        try:
            await coordinator.async_request_refresh()
        except Exception:
            _LOGGER.debug("Zigbee record heal: coordinator refresh failed", exc_info=True)
    # The rebuild listener creates the Home Layout selects and the card itself.
    async_dispatcher_send(hass, SIGNAL_DASHBOARD_REGEN_REQUESTED)
    return True


async def _async_add_heater_temp_source_select(
    hass: HomeAssistant, entry: ConfigEntry, device: dict[str, Any],
) -> None:
    """Create the heater's device-row selects for an Autoterm heater added (or
    reflashed) post-setup, or missed at setup: "Temperature Sensor Source" and
    "Heater Model". Each builder decides eligibility and returns [] otherwise.

    Keyed on a LIVE state, not a registry row: the row outlives a restart, so
    a select setup did not rebuild (its heater's ESPHome entities not loaded
    yet, no choice in the ledger) sat restored and "unavailable" for ever and
    the Devices row lost its dropdown (Living Heater on .228, 2026-10-11)."""
    from .const import HEATER_MODEL_UID_SUFFIX, HEATER_TEMP_SOURCE_UID_SUFFIX
    from .select import build_heater_model_selects, build_heater_temp_source_selects

    device_id = str(device.get("device_id") or device.get("id") or "")
    if not device_id:
        return
    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    add_selects = runtime.get("vendor_add_selects")
    if not add_selects:
        return
    for suffix, builder, label in (
        (HEATER_TEMP_SOURCE_UID_SUFFIX, build_heater_temp_source_selects,
         "Temperature Sensor Source"),
        (HEATER_MODEL_UID_SUFFIX, build_heater_model_selects, "Heater Model"),
    ):
        guard = f"heater_select{suffix}_{device_id}"
        if runtime.get(guard):
            continue
        try:
            from homeassistant.helpers.entity_registry import (
                async_get as async_get_entity_registry,
            )
            uid = f"{entry.entry_id}_{device_id}{suffix}"
            existing = async_get_entity_registry(hass).async_get_entity_id("select", DOMAIN, uid)
            state = hass.states.get(existing) if existing else None
            if state is not None and not state.attributes.get("restored"):
                runtime[guard] = True
                continue
        except Exception:  # noqa: BLE001, S110
            pass
        built = builder(hass, entry, device)
        if not built:
            continue  # not eligible (yet): asked again on the next rebuild
        add_selects(built)
        runtime[guard] = True
        _LOGGER.info("Added %s select for heater %s", label, device_id)


async def _async_add_mopeka_entities(
    hass: HomeAssistant, entry: ConfigEntry, device: dict[str, Any],
) -> None:
    """Create a Mopeka's Contents and Tank Shape selects, Tank Height number,
    Tank is Full button and % Tank Level sensor when they are missing post-setup (a Mopeka added from Discovery, or
    one registered before an entity was added to `mopeka.py`).

    Per entity, and keyed on a live STATE rather than a registry row: a row
    outlives a restart, so it cannot tell "created this run" from "created
    once, long ago"."""
    from .mopeka import (
        build_buttons,
        build_level_sensors,
        build_numbers,
        build_selects,
        is_mopeka,
    )

    if not is_mopeka(device):
        return
    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    add_selects = runtime.get("vendor_add_selects")
    add_numbers = runtime.get("vendor_add_numbers")
    add_buttons = runtime.get("vendor_add_button")
    add_sensors = runtime.get("vendor_add_sensors")
    if not add_selects or not add_numbers or not add_buttons or not add_sensors:
        return
    added: set[str] = runtime.setdefault("mopeka_added", set())
    for add, built in (
        (add_selects, build_selects(entry, device)),
        (add_numbers, build_numbers(entry, device)),
        (add_buttons, build_buttons(entry, device)),
        (add_sensors, build_level_sensors(entry, device)),
    ):
        new = [
            ent for ent in built
            if ent.entity_id not in added and hass.states.get(ent.entity_id) is None
        ]
        if new:
            add(new)
            added.update(ent.entity_id for ent in new)
            _LOGGER.info(
                "Added Mopeka entities %s", [ent.entity_id for ent in new],
            )


async def _async_add_diesel_entities(
    hass: HomeAssistant, entry: ConfigEntry, device: dict[str, Any],
) -> None:
    """Create an Autoterm heater's Diesel Use and Diesel Per Day sensors when
    it is added post-setup. sensor.py records the heaters it made them for, so
    a restart adds nothing twice."""
    from .diesel_use import build_heater_sensors, is_autoterm
    from .diesel_use import tracker as diesel_tracker

    device_id = str(device.get("device_id") or device.get("id") or "")
    if not device_id or not is_autoterm(device):
        return
    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    dt = diesel_tracker(hass, entry)
    if dt is not None:
        dt.revive_heater(device_id)  # listed again, so no longer retired
    add_sensors = runtime.get("vendor_add_sensors")
    added: set[str] | None = runtime.get("diesel_sensors_added")
    if not add_sensors or added is None or device_id in added:
        return
    added.add(device_id)
    name = str(device.get("display_name") or device.get("name") or "Heater")
    add_sensors(build_heater_sensors(entry, device_id, name))
    _LOGGER.info("Added diesel use sensors for heater %s", device_id)


