def _remove_header_short_name_entities(
    hass: HomeAssistant, entry: ConfigEntry, removed_device_ids: set[str],
) -> None:
    """Drop a removed device's short name and delete its field. Both halves,
    as for the chip ledgers: the options map is one of the field's build
    sources, so pruning only the entity would see it re-created."""
    from .const import HEADER_SHORT_NAME_OPTION, HEADER_SHORT_NAME_UID_SUFFIX

    options = getattr(entry, "options", None) or {}
    current = dict(options.get(HEADER_SHORT_NAME_OPTION) or {})
    kept = {k: v for k, v in current.items() if str(k) not in removed_device_ids}
    if kept != current:
        hass.config_entries.async_update_entry(
            entry, options={**options, HEADER_SHORT_NAME_OPTION: kept},
        )
    try:
        from homeassistant.helpers import entity_registry as er

        ent_reg = er.async_get(hass)
        for device_id in removed_device_ids:
            uid = f"{entry.entry_id}_{device_id}{HEADER_SHORT_NAME_UID_SUFFIX}"
            eid = ent_reg.async_get_entity_id("text", DOMAIN, uid)
            if eid:
                ent_reg.async_remove(eid)
    except Exception:
        _LOGGER.debug("header short-name orphan sweep raised", exc_info=True)


