@callback
def _async_ensure_light_type_selects(
    hass: HomeAssistant, entry: ConfigEntry,
) -> None:
    """Create any missing "Light Type" selects for Zigbee lighting controllers
    that appeared after platform setup. Mirrors `_async_ensure_led_strip_selects`
    but covers every Z2M light (not just addressable ones). Idempotent — dedups
    by unique_id against the entity registry."""
    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    add_selects = runtime.get("vendor_add_selects")
    try:
        from homeassistant.helpers import entity_registry as er

        from .select import build_light_type_selects

        ent_reg = er.async_get(hass)
        existing = {
            ent.unique_id
            for ent in ent_reg.entities.values()
            if ent.config_entry_id == entry.entry_id and ent.unique_id
        }
        wanted = build_light_type_selects(hass, entry)
        # Creation needs the platform callback; REMOVAL does not, and must not
        # wait for it. This runs at setup too, before select.py has stashed
        # `vendor_add_selects`, and returning early there would leave an orphan
        # on screen until a light entity happened to re-register.
        if add_selects is not None:
            new = [sel for sel in wanted if sel.unique_id not in existing]
            if new:
                add_selects(new)

        # AND REMOVE the ones that should no longer exist.
        #
        # Building fewer selects does not delete the ones already created:
        # they stay in the entity registry, keep their stored value, and keep
        # rendering on the device row. When addressable controllers stopped
        # being offered a Light Type, every WZ-SPI that already had one kept it,
        # still showing the old generic options. From the customer's side that
        # reads as the feature going backwards rather than being withdrawn
        # (2026-09-07).
        #
        # Same shape as the config-entity orphan the picker already guards
        # against: the set that SHOULD exist is the authority, and anything of
        # ours outside it is removed rather than left to linger.
        keep = {sel.unique_id for sel in wanted}
        prefix = f"{entry.entry_id}_light_type_"
        for ent in list(ent_reg.entities.values()):
            if ent.config_entry_id != entry.entry_id or not ent.unique_id:
                continue
            if not ent.unique_id.startswith(prefix) or ent.unique_id in keep:
                continue
            _LOGGER.info(
                "Light Type: removing %s — its controller is no longer offered "
                "one (addressable controllers set the strip, not a light type)",
                ent.entity_id,
            )
            ent_reg.async_remove(ent.entity_id)
    except Exception:  # pragma: no cover - defensive
        _LOGGER.debug("Ensuring light type selects failed", exc_info=True)


