async def _async_get_mode_overrides(hass: HomeAssistant, entry: ConfigEntry):
    """Return this entry's `ModeOverrides`, lazily creating + loading it if
    setup's bootstrap hasn't run yet."""
    from .modes import ModeOverrides

    # NB: not `... or {}` — an empty runtime dict is still THE runtime, and
    # the loaded store must land in it, not in a throwaway.
    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id)
    if runtime is None:
        runtime = {}
    overrides = runtime.get("mode_overrides")
    if overrides is None:
        overrides = ModeOverrides(hass)
        await overrides.async_load()
        runtime["mode_overrides"] = overrides
    return overrides


def _add_custom_mode_active_sensors(
    hass: HomeAssistant, entry: ConfigEntry, modes: list,
) -> None:
    """Give customer-created scenes their `binary_sensor.sensa_nomad_mode_<slug>_active`
    (the presets get theirs from the binary_sensor platform's own setup).
    Queued if the platform hasn't registered its add callback yet."""
    if not modes:
        return
    from .binary_sensor import SensaModeActiveBinarySensor

    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id)
    if runtime is None:
        return
    _add_or_queue_vendor_entities(
        runtime, "binary_sensors",
        [SensaModeActiveBinarySensor(entry, m) for m in modes],
    )


async def _async_handle_set_mode_home(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Put a scene on, or take it off, the Habitation Home page's mode bar
    (the "Include in Scenes card" tick in the scene popup). Broadcasts the
    catalog so the Home bar updates live."""
    from homeassistant.helpers.dispatcher import async_dispatcher_send

    from .const import SIGNAL_MODES_CHANGED

    mode_slug = str(call.data.get("mode") or "").strip().lower()
    home = bool(call.data.get("home"))
    overrides = await _async_get_mode_overrides(hass, entry)
    if overrides.get_mode_def(mode_slug) is None:
        _LOGGER.warning("set_mode_home: unknown mode %r", mode_slug)
        return
    if not await overrides.async_set_mode_home(mode_slug, home):
        return
    async_dispatcher_send(hass, SIGNAL_MODES_CHANGED, overrides.modes_payload())


async def _async_handle_set_mode_enabled(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Show / hide a preset (or custom) scene on the tiles, pills and tabs.
    Drive and Parked are locked (the instincts switch to them). Broadcasts
    the catalog so every card updates."""
    from homeassistant.helpers.dispatcher import async_dispatcher_send

    from .const import SIGNAL_MODES_CHANGED, SIGNAL_STARTUP_MODE_CHANGED

    mode_slug = str(call.data.get("mode") or "").strip().lower()
    enabled = bool(call.data.get("enabled"))
    overrides = await _async_get_mode_overrides(hass, entry)
    if overrides.get_mode_def(mode_slug) is None:
        _LOGGER.warning("set_mode_enabled: unknown mode %r", mode_slug)
        return
    startup_before = overrides.get_startup_mode()
    if not await overrides.async_set_mode_enabled(mode_slug, enabled):
        return
    if overrides.get_startup_mode() != startup_before:
        async_dispatcher_send(
            hass, SIGNAL_STARTUP_MODE_CHANGED, overrides.get_startup_mode() or "",
        )
    async_dispatcher_send(hass, SIGNAL_MODES_CHANGED, overrides.modes_payload())


async def _async_handle_create_mode(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Create a customer scene: persist it, give it an active sensor, regen
    scenes.yaml so `scene.nomad_<slug>` exists, and broadcast the catalog."""
    from homeassistant.helpers.dispatcher import async_dispatcher_send

    from .const import SIGNAL_MODES_CHANGED, SIGNAL_MODES_REGEN_REQUESTED

    name = str(call.data.get("name") or "").strip()
    if not name:
        _LOGGER.warning("create_mode: a name is required")
        return
    icon = call.data.get("icon")
    overrides = await _async_get_mode_overrides(hass, entry)
    mode = await overrides.async_create_mode(name, icon if isinstance(icon, str) else None)
    _add_custom_mode_active_sensors(hass, entry, [mode])
    async_dispatcher_send(hass, SIGNAL_MODES_CHANGED, overrides.modes_payload())
    async_dispatcher_send(hass, SIGNAL_MODES_REGEN_REQUESTED)


async def _async_handle_delete_mode(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Delete a customer scene (presets can only be hidden). Removes its
    active sensor, regenerates scenes.yaml without it, and broadcasts."""
    from homeassistant.helpers import entity_registry as er
    from homeassistant.helpers.dispatcher import async_dispatcher_send

    from .const import (
        SIGNAL_CURRENT_MODE_CHANGED,
        SIGNAL_MODES_CHANGED,
        SIGNAL_MODES_REGEN_REQUESTED,
        SIGNAL_STARTUP_MODE_CHANGED,
    )
    from .modes_catalog import mode_active_entity_id, scene_entity_id

    mode_slug = str(call.data.get("mode") or "").strip().lower()
    overrides = await _async_get_mode_overrides(hass, entry)
    if not overrides.is_custom(mode_slug):
        _LOGGER.warning("delete_mode: %r is not a customer-created scene", mode_slug)
        return
    startup_before = overrides.get_startup_mode()
    await overrides.async_delete_mode(mode_slug)
    # If the van is sitting in the deleted scene, it's now in none.
    current = hass.states.get("sensor.sensa_nomad_current_mode")
    if current is not None and (current.attributes or {}).get("slug") == mode_slug:
        async_dispatcher_send(hass, SIGNAL_CURRENT_MODE_CHANGED, "")
    if overrides.get_startup_mode() != startup_before:
        async_dispatcher_send(
            hass, SIGNAL_STARTUP_MODE_CHANGED, overrides.get_startup_mode() or "",
        )
    try:
        registry = er.async_get(hass)
        for entity_id in (mode_active_entity_id(mode_slug), scene_entity_id(mode_slug)):
            if registry.async_get(entity_id) is not None:
                registry.async_remove(entity_id)
    except Exception:
        _LOGGER.debug("delete_mode: entity cleanup raised", exc_info=True)
    async_dispatcher_send(hass, SIGNAL_MODES_CHANGED, overrides.modes_payload())
    async_dispatcher_send(hass, SIGNAL_MODES_REGEN_REQUESTED)


async def _async_handle_rename_mode(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Change a scene's display name / icon. Slugs never move, so nothing
    generated changes; just broadcast the catalog."""
    from homeassistant.helpers.dispatcher import async_dispatcher_send

    from .const import SIGNAL_MODES_CHANGED

    mode_slug = str(call.data.get("mode") or "").strip().lower()
    name = call.data.get("name")
    icon = call.data.get("icon")
    overrides = await _async_get_mode_overrides(hass, entry)
    result = await overrides.async_rename_mode(
        mode_slug,
        name if isinstance(name, str) else None,
        icon if isinstance(icon, str) else None,
    )
    if result is None:
        _LOGGER.warning("rename_mode: unknown mode %r", mode_slug)
        return
    async_dispatcher_send(hass, SIGNAL_MODES_CHANGED, overrides.modes_payload())


