async def _async_get_light_groups(hass: HomeAssistant, entry: ConfigEntry):
    """Return this entry's `LightGroupStore`, lazily creating + loading it if
    setup's bootstrap hasn't run yet (mirrors `_async_get_mode_overrides`)."""
    from .light_groups import LightGroupStore

    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id)
    if runtime is None:
        runtime = {}
    store = runtime.get("light_groups")
    if store is None:
        store = LightGroupStore(hass)
        await store.async_load()
        runtime["light_groups"] = store
    return store


def _add_light_group_entities(
    hass: HomeAssistant, entry: ConfigEntry, groups: list,
) -> None:
    """Give each group its `light.sensa_nomad_group_<slug>` entity. Queued if
    the light platform hasn't registered its add callback yet -- it has not on
    a cold boot, because the group store loads after the platform forward."""
    if not groups:
        return
    from .light import SensaLightGroup

    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id)
    if runtime is None:
        return
    _add_or_queue_vendor_entities(
        runtime, "lights", [SensaLightGroup(entry, g) for g in groups],
    )


def _broadcast_light_groups(hass: HomeAssistant, store) -> None:
    """Tell every group entity (and the Light Groups card) the catalog moved."""
    from homeassistant.helpers.dispatcher import async_dispatcher_send

    from .const import SIGNAL_LIGHT_GROUPS_CHANGED

    async_dispatcher_send(hass, SIGNAL_LIGHT_GROUPS_CHANGED, store.groups_payload())


def _rebuild_lighting_cards(hass: HomeAssistant) -> None:
    """Ask for a dashboard regen so the Lighting tab gains / loses the group's
    card. Membership changes don't need this -- the card renders from the live
    entity -- but a create, delete, rename or reorder changes the card LIST."""
    from homeassistant.helpers.dispatcher import async_dispatcher_send

    from .const import SIGNAL_DASHBOARD_REGEN_REQUESTED

    async_dispatcher_send(hass, SIGNAL_DASHBOARD_REGEN_REQUESTED)


async def _async_prune_light_groups(
    hass: HomeAssistant, entry: ConfigEntry,
) -> None:
    """Drop group members that are no longer lights the customer owns.

    Pruned against the CANDIDATE set -- the same list the picker offers, which
    is the registered lighting devices plus the relay channels declared as
    lighting. One definition of "may be in a group", so a member cannot outlive
    the rule that let it in.

    It used to prune against every `light.*` row in the entity registry, and
    that answered a different question: a light the customer deletes in Sensa
    can keep its HA registry row (Z2M is slow to retract its discovery, or the
    device was only unregistered from Sensa), so the deleted light stayed in
    the group for ever (Richard, 2026-09-18). It also had no idea a relay
    channel could be a member, so it would have pruned every one of them.

    Still resolved from the entity registry underneath, never from
    `hass.states`: a registry row survives a restart, a reload and a vendor
    backend outage, and pruning on a missing state would quietly empty a group
    every time its lights were slow to come back. An empty candidate list is
    "could not ask" and prunes nothing (`async_prune_members`).
    """
    from .dashboard import light_group_candidate_entities

    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    store = runtime.get("light_groups")
    if store is None:
        return
    try:
        known = {
            str(c.get("entity"))
            for c in light_group_candidate_entities()
            if c.get("entity")
        }
        if await store.async_prune_members(known):
            _broadcast_light_groups(hass, store)
    except Exception:
        _LOGGER.debug("light group prune raised", exc_info=True)


async def _async_handle_create_light_group(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Create a light group, give it its light entity, and broadcast."""
    name = str(call.data.get("name") or "").strip()
    if not name:
        _LOGGER.warning("create_light_group: a name is required")
        return
    icon = call.data.get("icon")
    store = await _async_get_light_groups(hass, entry)
    group = await store.async_create(
        name,
        icon if isinstance(icon, str) else None,
        call.data.get("members"),
    )
    _add_light_group_entities(hass, entry, [group])
    _broadcast_light_groups(hass, store)
    _rebuild_lighting_cards(hass)


async def _async_handle_delete_light_group(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Delete a light group. The member lights are untouched; only the group's
    own entity goes, and its registry row with it so the id is reusable."""
    from homeassistant.helpers import entity_registry as er

    from .light_groups import light_group_entity_id

    slug = str(call.data.get("group") or "").strip().lower()
    store = await _async_get_light_groups(hass, entry)
    if not await store.async_delete(slug):
        _LOGGER.warning("delete_light_group: unknown group %r", slug)
        return
    try:
        registry = er.async_get(hass)
        entity_id = light_group_entity_id(slug)
        if registry.async_get(entity_id) is not None:
            registry.async_remove(entity_id)
    except Exception:
        _LOGGER.debug("delete_light_group: entity cleanup raised", exc_info=True)
    _broadcast_light_groups(hass, store)
    _rebuild_lighting_cards(hass)


async def _async_handle_rename_light_group(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Change a group's display name / icon. Slugs never move, so nothing
    referencing the group changes; just broadcast."""
    slug = str(call.data.get("group") or "").strip().lower()
    name = call.data.get("name")
    icon = call.data.get("icon")
    store = await _async_get_light_groups(hass, entry)
    if await store.async_rename(
        slug,
        name if isinstance(name, str) else None,
        icon if isinstance(icon, str) else None,
    ) is None:
        _LOGGER.warning("rename_light_group: unknown group %r", slug)
        return
    _broadcast_light_groups(hass, store)
    _rebuild_lighting_cards(hass)


async def _async_handle_set_light_group_members(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Replace a group's membership. The group entity re-subscribes to the new
    list off the broadcast, so the change is live without a reload."""
    slug = str(call.data.get("group") or "").strip().lower()
    store = await _async_get_light_groups(hass, entry)
    if await store.async_set_members(slug, call.data.get("members")) is None:
        _LOGGER.warning("set_light_group_members: unknown group %r", slug)
        return
    _broadcast_light_groups(hass, store)


async def _async_handle_set_lighting_card_order(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Persist the order the customer dragged the Lights tab into.

    One list of card entity ids covering groups AND individual lights, because
    they share one grid. Stored on `entry.options` rather than in the light-
    group store: that store only knows about groups, and half an order is worse
    than none.

    Rebuilds the dashboards, for the same reason the Home-layout order number
    does: an options write alone changes nothing on screen, so the drag would
    appear to work and then snap back on the next refresh.
    """
    from .const import LIGHTING_CARD_ORDER_OPTION

    raw = call.data.get("order")
    order = [
        str(item) for item in raw or [] if isinstance(item, str) and item
    ]
    if order == list(entry.options.get(LIGHTING_CARD_ORDER_OPTION) or []):
        return
    hass.config_entries.async_update_entry(
        entry,
        options={**entry.options, LIGHTING_CARD_ORDER_OPTION: order},
    )
    _rebuild_lighting_cards(hass)


async def _async_handle_set_light_group_order(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Persist the customer's display order for the light groups."""
    store = await _async_get_light_groups(hass, entry)
    await store.async_set_order(call.data.get("order"))
    _broadcast_light_groups(hass, store)
    _rebuild_lighting_cards(hass)


async def _async_get_routine_overrides(hass: HomeAssistant, entry: ConfigEntry):
    """Return this entry's `RoutineOverrides`, lazily creating + loading it
    if setup's bootstrap hasn't run yet (mirrors `_async_handle_update_mode`'s
    equivalent lazy-init for `mode_overrides`)."""
    from .routines import RoutineOverrides

    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    overrides = runtime.get("routine_overrides")
    if overrides is None:
        overrides = RoutineOverrides(hass)
        await overrides.async_load()
        runtime["routine_overrides"] = overrides
    return overrides


async def _async_regen_routines(hass: HomeAssistant, entry: ConfigEntry) -> None:
    """Rebuild routines.yaml + reload, called directly after every
    save/delete/enable — no debounce needed since each is one explicit
    customer action, not a device-churn burst (contrast
    `_register_modes_regen_listener`)."""
    from .routines import async_create_or_update_sensa_routines, async_reload_routines

    overrides = await _async_get_routine_overrides(hass, entry)
    await async_create_or_update_sensa_routines(hass, overrides)
    await async_reload_routines(hass)

    # Push the sensor the card reads, or the tile the customer just created or
    # deleted sits there until the entity's own 30-second poll comes round and
    # the only thing that looks broken is us. The sensor reads the override
    # store live, so writing state is all it needs.
    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    sensor = runtime.get("routines_sensor")
    if sensor is not None:
        try:
            sensor.async_write_ha_state()
        except Exception:
            _LOGGER.debug("routines sensor state push failed", exc_info=True)


async def _async_handle_save_routine(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Persist a customer-authored routine (create or full replace) and
    regenerate routines.yaml. Called by the sensa-routines-card's Save
    button."""
    from homeassistant.exceptions import HomeAssistantError

    actions = [dict(a) for a in call.data.get("actions") or []]
    if not actions and call.data.get("action"):
        actions = [dict(call.data["action"])]
    if not actions:
        raise HomeAssistantError("A routine needs at least one Then Do action.")
    overrides = await _async_get_routine_overrides(hass, entry)
    await overrides.async_save_routine(
        str(call.data["routine_id"]),
        name=str(call.data["name"]),
        enabled=bool(call.data["enabled"]),
        trigger=dict(call.data["trigger"]),
        conditions=list(call.data.get("conditions") or []),
        actions=actions,
    )
    await _async_regen_routines(hass, entry)


async def _async_handle_delete_routine(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    overrides = await _async_get_routine_overrides(hass, entry)
    await overrides.async_delete_routine(str(call.data["routine_id"]))
    await _async_regen_routines(hass, entry)


async def _async_handle_set_routine_order(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Persist the Routines tiles' drag order, then push the routines sensor
    so every screen shows it at once. The order changes no automation, so
    routines.yaml is not regenerated."""
    overrides = await _async_get_routine_overrides(hass, entry)
    if not await overrides.async_set_order(call.data.get("order")):
        return
    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    sensor = runtime.get("routines_sensor")
    if sensor is not None and sensor.hass is not None:
        sensor.async_write_ha_state()


async def _async_handle_set_routine_enabled(
    hass: HomeAssistant, entry: ConfigEntry, call: ServiceCall,
) -> None:
    """Fast enable/disable toggle from the routines list, without reopening
    the editor (mirrors the Instincts tab's toggle-only interaction)."""
    overrides = await _async_get_routine_overrides(hass, entry)
    await overrides.async_set_enabled(
        str(call.data["routine_id"]), bool(call.data["enabled"]),
    )
    await _async_regen_routines(hass, entry)


@callback
async def _async_post_reset_mode_when_running(hass: HomeAssistant) -> None:
    """Activate the post-reset mode on an entry set up after HA started.

    Waits briefly so the fresh entry's scenes exist, then consumes the marker.
    A normal reload has no marker and does nothing.
    """
    from homeassistant.helpers.storage import Store

    from .factory_reset import POST_RESET_STORE_KEY

    try:
        marker_store = Store(hass, 1, POST_RESET_STORE_KEY)
        marker = await marker_store.async_load()
        if not (isinstance(marker, dict) and marker.get("mode")):
            return
        await asyncio.sleep(30)
        await marker_store.async_remove()
        await hass.services.async_call(
            DOMAIN, "activate_mode", {"mode": str(marker["mode"])}, blocking=False,
        )
    except Exception:
        _LOGGER.warning("startup mode: post-reset mode not applied", exc_info=True)


def _async_schedule_startup_mode_activation(
    hass: HomeAssistant, entry: ConfigEntry,
) -> None:
    """Fire the customer's pinned startup mode once HA is fully started.

    On a real HA restart `async_setup_entry` runs while core is still
    starting — listen for `EVENT_HOMEASSISTANT_STARTED` so scenes and
    contributing entities are guaranteed registered before we trigger.
    On an integration reload (HA already running) we deliberately
    skip: the current mode is whatever's live right now, no need for
    a startup-mode override mid-session.
    """
    from homeassistant.const import EVENT_HOMEASSISTANT_STARTED
    from homeassistant.core import CoreState

    if hass.state != CoreState.starting and hass.state != CoreState.not_running:
        # The entry a factory reset re-creates can finish setting up after HA
        # has started; the post-reset Parked start must still happen then.
        hass.async_create_task(_async_post_reset_mode_when_running(hass))
        return

    from .modes_catalog import STARTUP_MODE_PREVIOUS

    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id) or {}
    overrides = runtime.get("mode_overrides")
    if overrides is None:
        return
    startup_slug = overrides.get_startup_mode()
    # "previous" restores whatever mode was active before this restart.
    if startup_slug == STARTUP_MODE_PREVIOUS:
        startup_slug = overrides.get_last_active_mode() or ""

    async def _activate(_event: Any) -> None:
        from homeassistant.core import Context
        from homeassistant.helpers.storage import Store

        from .factory_reset import POST_RESET_STORE_KEY

        # The first boot after a factory reset starts in Parked, whatever the
        # (freshly re-seeded) startup pin says. One-shot: the marker goes.
        slug = startup_slug
        try:
            marker_store = Store(hass, 1, POST_RESET_STORE_KEY)
            marker = await marker_store.async_load()
            if isinstance(marker, dict) and marker.get("mode"):
                slug = str(marker["mode"])
                await marker_store.async_remove()
        except Exception:
            _LOGGER.warning("startup mode: post-reset marker unreadable", exc_info=True)
        if not slug:
            return

        # Remembered so the log line can say "on start-up" rather than
        # guessing an automation from a context HA mints for every call.
        context = Context()
        hass.data.setdefault(DOMAIN, {}).setdefault(
            _STARTUP_MODE_CONTEXTS, set(),
        ).add(context.id)
        try:
            await hass.services.async_call(
                DOMAIN, "activate_mode", {"mode": slug},
                blocking=False, context=context,
            )
        except Exception:
            _LOGGER.warning(
                "startup mode: failed to activate %r on HA start",
                slug, exc_info=True,
            )

    hass.bus.async_listen_once(EVENT_HOMEASSISTANT_STARTED, _activate)


def _attach_bms_entity_prefixes(
    hass: HomeAssistant,
    entry_id: str,
    devices: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Return a copy of `devices` with a `bms_entities` role-map
    attached to every `sensa_bms_ble` row.

    Each map entry is {role_slug: entity_id}. `role_slug` is the
    slugified original_name of the entity (e.g. "state_of_charge",
    "pack_voltage", "fault") — stable across device renames because
    `has_entity_name=True` + `_attr_name` land in the entity
    registry as `original_name` at first registration and are never
    updated automatically. The value is the real entity_id the
    registry holds, so the dashboard doesn't have to guess slugs.

    We also carry `bms_family` out of the device config so the card
    builder can tailor the layout (VIP packs don't have State of
    Health / active balancing; JK packs do).

    On a freshly-added pack the entity registry won't have entries
    yet (this runs before platform setup), so `bms_entities` will be
    empty — that's fine; the card builder renders an empty row in
    that case and the next regen (after enrichment or the next
    add/remove) fills it in.
    """
    try:
        from homeassistant.helpers import entity_registry as er
        from homeassistant.util import slugify as _ha_slugify
    except ImportError:
        return list(devices)
    try:
        ent_reg = er.async_get(hass)
    except Exception:  # noqa: BLE001
        return list(devices)

    enriched: list[dict[str, Any]] = []
    for dev in devices:
        integration = (
            dev.get("integration_type") or dev.get("integration") or ""
        )
        device_id = dev.get("device_id")
        if integration != "sensa_bms_ble" or not device_id:
            enriched.append(dev)
            continue

        marker = f"_bms_{device_id}_"
        role_map: dict[str, str] = {}
        for ent in ent_reg.entities.values():
            uid = ent.unique_id or ""
            if marker not in uid:
                continue
            original = getattr(ent, "original_name", None) or ""
            if not original:
                # No name stored — fall back to the unique_id key so
                # at least the entity is reachable under some label.
                original = uid.split(marker, 1)[1]
            role_slug = _ha_slugify(original)
            if not role_slug:
                continue
            # First hit per role wins (an entity shouldn't collide,
            # but if it does we stick with the first-seen one).
            role_map.setdefault(role_slug, ent.entity_id)

        dev_copy = dict(dev)
        if role_map:
            dev_copy["bms_entities"] = role_map
        enriched.append(dev_copy)
    return enriched


def _victron_ble_battery_role(tag: str) -> str:
    """Map a victron_ble battery entity's translation_key / name to a
    BMS-card role slug, or "" if it isn't one we surface.

    Cell first (a "Cell 1 Voltage" entity also contains "voltage"), then
    balancer, then temperature, then the pack voltage. A Smart Lithium's
    BLE record has no SoC/current (Victron computes those in the shunt /
    GX), so those roles never appear here — the card shows cell health.
    """
    import re

    m = re.search(r"cell[\s_]*0*(\d+)", tag)
    if m:
        return f"cell_{int(m.group(1))}_voltage"
    if "balanc" in tag:
        return "balancing"
    if "temp" in tag:
        return "battery_temp_1"
    if "voltage" in tag:
        return "pack_voltage"
    return ""


def _victron_ble_battery_role_map(
    dev_reg: Any, ent_reg: Any, mac: str,
) -> dict[str, str]:
    """Build a `bms_entities` role map from an adopted victron_ble
    battery's HA entities, found by Bluetooth MAC. Empty dict if the HA
    device / entities aren't registered yet (the regen listener re-runs
    this once victron_ble finishes setting up its cell sensors)."""
    if not mac:
        return {}
    mac_canon = mac.replace("-", ":").upper()
    if ":" not in mac_canon and len(mac_canon) == 12:
        mac_canon = ":".join(mac_canon[i:i + 2] for i in range(0, 12, 2))
    try:
        from homeassistant.helpers import entity_registry as er
        from homeassistant.helpers.device_registry import CONNECTION_BLUETOOTH
        device = dev_reg.async_get_device(
            connections={(CONNECTION_BLUETOOTH, mac_canon)},
        )
    except Exception:  # noqa: BLE001
        device = None
    if device is None:
        return {}
    role_map: dict[str, str] = {}
    try:
        entries = er.async_entries_for_device(
            ent_reg, device.id, include_disabled_entities=False,
        )
    except Exception:  # noqa: BLE001
        return {}
    for ent in entries:
        tag = (
            getattr(ent, "translation_key", None)
            or getattr(ent, "original_name", None)
            or ent.unique_id
            or ""
        ).lower()
        role = _victron_ble_battery_role(tag)
        if role:
            role_map.setdefault(role, ent.entity_id)
    return role_map


def _attach_victron_ble_battery_roles(
    hass: HomeAssistant,
    entry_id: str,
    devices: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Attach a `bms_entities` role map to an adopted Victron Smart Lithium
    (integration `victron_ble`, service class `battery`).

    Unlike a Sensa-owned `sensa_bms_ble` pack (which carries a `_bms_<id>_`
    unique-id marker), the Smart Lithium is owned by HA core's victron_ble
    integration (Adopt method), so we locate its HA device by Bluetooth MAC
    and map the native entities into the BMS-card vocabulary. Runs before
    `_attach_service_class_rows`, mirroring `_attach_bms_entity_prefixes`.
    SmartShunt / SmartSolar (also victron_ble) are skipped — they're not
    `battery` service class.
    """
    try:
        from homeassistant.helpers import device_registry as dr
        from homeassistant.helpers import entity_registry as er
    except ImportError:
        return list(devices)
    try:
        dev_reg = dr.async_get(hass)
        ent_reg = er.async_get(hass)
    except Exception:  # noqa: BLE001
        return list(devices)

    enriched: list[dict[str, Any]] = []
    for dev in devices:
        integration = (
            dev.get("integration_type") or dev.get("integration") or ""
        )
        is_lithium = (
            integration == "victron_ble"
            and (
                dev.get("device_subtype") == "smartlithium"
                or dev.get("vendor_model") == "victron_smartlithium"
                or dev.get("service_class") == "battery"
            )
        )
        if not is_lithium:
            enriched.append(dev)
            continue
        mac = dev.get("linked_mac_address") or dev.get("mac_address") or ""
        role_map = _victron_ble_battery_role_map(dev_reg, ent_reg, mac)
        dev_copy = dict(dev)
        if role_map:
            dev_copy["bms_entities"] = role_map
        # Guarantee the leisure-battery classification even before
        # `classify()` runs, so `_is_leisure_battery` routes it to the BMS
        # tab whether or not the backend row carried `service_class`.
        dev_copy.setdefault("service_class", "battery")
        enriched.append(dev_copy)
    return enriched


def _victron_ble_battery_protect_role(tag: str) -> str:
    """Map a victron_ble BatteryProtect entity's translation_key / name to a
    BatteryProtect-card role slug, or "" if it isn't one we surface.

    Forgiving substring match (same approach as `_victron_ble_battery_role`)
    so it's robust to the exact entity keys HA core's `victron_ble` integration
    uses for a SmartBatteryProtect. Order matters: voltage rows are split by the
    input/output prefix first, and "device state" is matched before the bare
    "output state" so the two don't collide.
    """
    t = tag.lower()
    has_volt = "volt" in t
    if has_volt and "input" in t:
        return "input_voltage"
    if has_volt and "output" in t:
        return "output_voltage"
    if "off" in t and "reason" in t:
        return "off_reason"
    if "device" in t and "state" in t:
        return "device_state"
    if "output" in t and ("state" in t or "status" in t):
        return "output_state"
    if "warn" in t:
        return "warning_reason"
    if "alarm" in t:
        return "alarm_reason"
    if "error" in t:
        return "error_code"
    return ""


def _victron_ble_battery_protect_role_map(
    dev_reg: Any, ent_reg: Any, mac: str,
) -> dict[str, str]:
    """Build a `service_entities` role map from an adopted victron_ble
    BatteryProtect's HA entities, found by Bluetooth MAC. Empty dict if the HA
    device / entities aren't registered yet (the regen listener re-runs this
    once victron_ble finishes setting up). Mirrors
    `_victron_ble_battery_role_map`."""
    if not mac:
        return {}
    mac_canon = mac.replace("-", ":").upper()
    if ":" not in mac_canon and len(mac_canon) == 12:
        mac_canon = ":".join(mac_canon[i:i + 2] for i in range(0, 12, 2))
    try:
        from homeassistant.helpers import entity_registry as er
        from homeassistant.helpers.device_registry import CONNECTION_BLUETOOTH
        device = dev_reg.async_get_device(
            connections={(CONNECTION_BLUETOOTH, mac_canon)},
        )
    except Exception:  # noqa: BLE001
        device = None
    if device is None:
        return {}
    role_map: dict[str, str] = {}
    try:
        entries = er.async_entries_for_device(
            ent_reg, device.id, include_disabled_entities=False,
        )
    except Exception:  # noqa: BLE001
        return {}
    for ent in entries:
        tag = (
            getattr(ent, "translation_key", None)
            or getattr(ent, "original_name", None)
            or ent.unique_id
            or ""
        ).lower()
        role = _victron_ble_battery_protect_role(tag)
        if role:
            role_map.setdefault(role, ent.entity_id)
    return role_map


def _attach_victron_ble_battery_protect_roles(
    hass: HomeAssistant,
    entry_id: str,
    devices: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Attach a `service_entities` role map to an adopted Victron Smart
    BatteryProtect (integration `victron_ble`, subtype/service-class
    `battery_protect`).

    Owned by HA core's victron_ble integration (Adopt method), so we locate its
    HA device by Bluetooth MAC and map the native entities into the
    BatteryProtect card's vocabulary. Mirrors `_attach_victron_ble_battery_roles`;
    runs before `_attach_service_class_rows`.
    """
    try:
        from homeassistant.helpers import device_registry as dr
        from homeassistant.helpers import entity_registry as er
    except ImportError:
        return list(devices)
    try:
        dev_reg = dr.async_get(hass)
        ent_reg = er.async_get(hass)
    except Exception:  # noqa: BLE001
        return list(devices)

    enriched: list[dict[str, Any]] = []
    for dev in devices:
        integration = (
            dev.get("integration_type") or dev.get("integration") or ""
        )
        is_bp = (
            integration == "victron_ble"
            and (
                dev.get("device_subtype") == "battery_protect"
                or dev.get("service_class") == "battery_protect"
            )
        )
        if not is_bp:
            enriched.append(dev)
            continue
        mac = dev.get("linked_mac_address") or dev.get("mac_address") or ""
        role_map = _victron_ble_battery_protect_role_map(dev_reg, ent_reg, mac)
        dev_copy = dict(dev)
        if role_map:
            dev_copy["service_entities"] = role_map
        dev_copy.setdefault("service_class", "battery_protect")
        enriched.append(dev_copy)
    return enriched


@callback
async def _async_voice_refresh(hass: HomeAssistant, entry_id: str) -> None:
    """Bring voice control in line with the last eligibility pass, the scene
    list and the licence (`voice.py`). A no-op until a Voice device is added."""
    runtime = hass.data.get(DOMAIN, {}).get(entry_id)
    if not isinstance(runtime, dict) or not runtime.get("voice_inputs"):
        return
    devices, entities, names = runtime["voice_inputs"]
    overrides = runtime.get("mode_overrides")
    modes = overrides.modes_payload() if overrides is not None else None
    try:
        from .voice import async_refresh

        await async_refresh(hass, entry_id, devices, entities, names, modes)
    except Exception:  # voice must never break a rebuild
        _LOGGER.warning("Voice refresh failed", exc_info=True)


def _async_compute_and_broadcast_eligibility(
    hass: HomeAssistant,
    entry: ConfigEntry,
    devices: list[dict[str, Any]],
) -> None:
    """Recompute the Mode Editor's eligible-entity set and broadcast it.

    Called right after every `set_dashboard_devices` so the rule
    pipeline sees the freshest `vendor_device_type` mapping (relay /
    bms / teltonika / starlink). The result is broadcast via
    `SIGNAL_MODE_ELIGIBILITY_CHANGED` for the eligibility sensor and
    cached in runtime so a sensor that's still adding can pick up the
    snapshot in `async_added_to_hass` without missing the signal.
    """
    from homeassistant.helpers.dispatcher import async_dispatcher_send

    from .const import (
        SIGNAL_MODE_ELIGIBILITY_CHANGED,
        SIGNAL_ROUTINE_ELIGIBILITY_CHANGED,
    )
    from .mode_eligibility import (
        DEFAULT_RULES,
        ROUTINE_TRIGGER_RULES,
        compute_alarm_entities,
        compute_eligible_entities,
        compute_entity_devices,
        compute_entity_names,
        compute_entity_types,
        compute_presence_entities,
        compute_service_entities,
    )

    try:
        entities, traces = compute_eligible_entities(hass, devices)
    except Exception:
        _LOGGER.warning(
            "Mode eligibility compute failed; dropdown will be empty until next regen",
            exc_info=True,
        )
        return

    # Resolve a display name per eligible entity (relay channels → the
    # customer's Switching-tab label) so the editor's rows show meaningful
    # names, not raw entity_ids. Best-effort: an empty map just degrades to
    # the editor's own friendly_name fallback.
    try:
        names = compute_entity_names(hass, devices, entities)
    except Exception:  # noqa: BLE001
        names = {}
    # What each entity IS (icon + label + category), for the Scenes popup's
    # Add-items picker, which shows no entity ids. Best-effort like the names.
    try:
        types = compute_entity_types(hass, devices, entities)
    except Exception:  # noqa: BLE001
        types = {}

    runtime = hass.data.get(DOMAIN, {}).get(entry.entry_id)
    if isinstance(runtime, dict):
        runtime["mode_eligibility_snapshot"] = (entities, names, traces, types)

    async_dispatcher_send(
        hass, SIGNAL_MODE_ELIGIBILITY_CHANGED, entities, names, traces, types,
    )

    # Voice speaks the same controllable set the Scenes editor offers, so it is
    # refreshed from this one pass rather than from a list of its own.
    if isinstance(runtime, dict):
        runtime["voice_inputs"] = (list(devices), list(entities), dict(names))
    hass.async_create_task(_async_voice_refresh(hass, entry.entry_id))

    # A device removal can leave a light group pointing at an entity that no
    # longer exists. The group entity already ignores a missing member, so
    # this is tidiness, not correctness — which is why it is fire-and-forget.
    hass.async_create_task(_async_prune_light_groups(hass, entry))

    # Routine Editor's three picker groups, computed from the same device
    # list (piggybacked on this call site rather than a second listener —
    # see `mode_eligibility.ROUTINE_TRIGGER_RULES`'s docstring for why the
    # rule sets differ from the Mode Editor's).
    try:
        device_entities, _ = compute_eligible_entities(
            hass, devices, rules=ROUTINE_TRIGGER_RULES,
        )
        action_entities, _ = compute_eligible_entities(
            hass, devices, rules=DEFAULT_RULES,
        )
        # SensaClimate's target is the hub's own number, so the Sensa-device rule
        # never sweeps it in. A routine can set or turn it once its card exists.
        from .const import CLIMATE_CONTROL_TARGET_ENTITY_ID
        from .dial import climate_available

        if climate_available() and CLIMATE_CONTROL_TARGET_ENTITY_ID not in action_entities:
            action_entities = [*action_entities, CLIMATE_CONTROL_TARGET_ENTITY_ID]
        service_entities = compute_service_entities(hass)
        # The Routine Editor's other two When groups: who is in the van, and
        # whether an alarm is up. Their own lists, not folded into the device
        # one, because the picker offers them as groups of their own.
        presence_entities = compute_presence_entities(hass)
        alarm_entities = compute_alarm_entities(hass)
        routine_names = compute_entity_names(
            hass, devices, sorted({
                *device_entities, *service_entities, *action_entities,
                *presence_entities, *alarm_entities,
            }),
        )
        # Then Do's Device-target mode groups action_entities by owning
        # device (target: device_id — see compute_entity_devices' docstring);
        # scoped to action_entities only, since Device mode is a Then Do
        # concept, not a When/And If one.
        entity_devices = compute_entity_devices(hass, action_entities, devices)
        # What each entity IS (label + icon + category title), so the popup's
        # pickers can group by category and show a name only — never an
        # entity_id. Same map the Scenes popup reads, over the routine sets.
        routine_types = compute_entity_types(
            hass, devices, sorted({
                *device_entities, *service_entities, *action_entities,
                *presence_entities, *alarm_entities,
            }),
        )
    except Exception:
        _LOGGER.warning(
            "Routine eligibility compute failed; pickers will be empty until "
            "next regen", exc_info=True,
        )
        return

    # What the When picker will actually be able to offer, by the category it
    # files each entity under. The picker is the only place this is visible,
    # and "I cannot find my device in it" is otherwise unanswerable from
    # outside the box: the eligibility sensor is not restored to disk, so
    # there is nothing to read after the fact. An entity with no category
    # lands in the picker's "Other" group, so a large `-` count is itself the
    # answer to a device that has gone missing from every named group.
    if _LOGGER.isEnabledFor(logging.DEBUG):
        by_category: dict[str, int] = {}
        for _eid in device_entities:
            _cat = (routine_types.get(_eid) or {}).get("category_label") or "-"
            by_category[_cat] = by_category.get(_cat, 0) + 1
        _LOGGER.debug(
            "Routine When picker: %d entities, by category %s",
            len(device_entities), dict(sorted(by_category.items())),
        )

    if isinstance(runtime, dict):
        runtime["routine_eligibility_snapshot"] = (
            device_entities, service_entities, action_entities, routine_names,
            entity_devices, routine_types, presence_entities, alarm_entities,
        )

    async_dispatcher_send(
        hass, SIGNAL_ROUTINE_ELIGIBILITY_CHANGED,
        device_entities, service_entities, action_entities, routine_names,
        entity_devices, routine_types, presence_entities, alarm_entities,
    )


# The per-port tail of a Teltonika unique_id, i.e. what follows the
# `{entry_id}_teltonika_` marker. Mirrors the ids minted in
# `vendors/teltonika_entities.py` by `TeltonikaPortLink` (link),
# `TeltonikaPortPoe` (poe) and `TeltonikaPortPoeSwitch` (poe_power); change any
# of those unique_ids and this must follow, or the switch card silently loses
# its faceplate or its PoE controls.
# `poe_power` (the switch) is listed BEFORE `poe` (the binary_sensor) so the
# longer name wins; both are anchored, so the order is belt-and-braces.
_TELTONIKA_PORT_UID_RE = re.compile(
    r"^port_(?P<index>\d+)_(?P<kind>link|poe_power|poe)$"
)


def _attach_network_entity_prefixes(
    hass: HomeAssistant,
    entry_id: str,
    devices: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Return a copy of `devices` with a `network_entities` role-map
    attached to every Teltonika and Starlink row.

    Mirrors `_attach_bms_entity_prefixes`: each map entry is
    `{role_slug: entity_id}` keyed off the slugified `original_name`
    that lands in the entity registry the first time the entity is
    registered (stable across device renames). The Habitation Network
    view consumes this map so cards never slug-guess entity IDs from
    a device's display name.

    Empty map on freshly-added devices (registry not yet populated);
    the card builder handles that gracefully and the next regen fills
    it in.
    """
    try:
        from homeassistant.helpers import entity_registry as er
        from homeassistant.util import slugify as _ha_slugify

        from .vendors.teltonika_entities import teltonika_unique_id_prefix
    except ImportError:
        return list(devices)
    try:
        ent_reg = er.async_get(hass)
    except Exception:  # noqa: BLE001
        return list(devices)

    enriched: list[dict[str, Any]] = []
    for dev in devices:
        integration = (
            dev.get("integration_type") or dev.get("integration") or ""
        )
        if integration not in ("sensa_teltonika_api", "sensa_starlink_grpc"):
            enriched.append(dev)
            continue

        # Teltonika unique_ids are scoped PER DEVICE
        #   {entry_id}_teltonika_{device_id}_{key}            (generic sensors)
        #   {entry_id}_teltonika_{device_id}_wan_status       (WAN binary sensor)
        #   {entry_id}_teltonika_{device_id}_port_N_link      (per-port sensors)
        # An entry-scoped marker matched EVERY Teltonika, so on a van with a
        # router and a switch both rows resolved to the same mixed set of
        # entities and the switch card would have shown the router's model.
        # (`teltonika_entities.migrate_unique_ids` re-keys older boxes.)
        # Starlink unique_ids stay entry-scoped
        #   {entry_id}_starlink_{key}
        # (a Base licence supports a single dish, and nothing here mints a
        # second one, so there is no namespace to share).
        marker = (
            teltonika_unique_id_prefix(entry_id, dev.get("device_id") or "")
            if integration == "sensa_teltonika_api"
            else f"{entry_id}_starlink_"
        )

        role_map: dict[str, str] = {}
        # Ethernet ports, keyed by the port INDEX baked into the unique_id
        # rather than by the slugified name. The name is the customer-facing
        # label ("LAN1", "WAN") and is not sortable (RutOS returns the ROLE in
        # `name`, so three LAN ports can share it), while the index is the
        # physical order the switch faceplate has to be drawn in.
        ports: dict[int, dict[str, Any]] = {}
        for ent in ent_reg.entities.values():
            uid = ent.unique_id or ""
            if not uid.startswith(marker):
                continue
            original = getattr(ent, "original_name", None) or ""
            if not original:
                continue
            role_slug = _ha_slugify(original)
            if not role_slug:
                continue
            role_map.setdefault(role_slug, ent.entity_id)

            port_match = _TELTONIKA_PORT_UID_RE.match(uid[len(marker):])
            if port_match:
                index = int(port_match.group("index"))
                kind = port_match.group("kind")
                # "LAN1 Link" / "LAN1 PoE" / "LAN1 PoE Power" -> "LAN1". The
                # entity names are built from the label in
                # `teltonika_entities.create_port_entities`, so stripping the
                # suffix recovers it without a second source of truth.
                suffix = {
                    "link": " Link",
                    "poe": " PoE",
                    "poe_power": " PoE Power",
                }[kind]
                label = original.removesuffix(suffix)
                # A RUTX11 reports its port id as "_lan2"; the underscore is an
                # internal interface prefix, not a customer-facing label.
                # `_port_label` strips it for NEW registrations, but
                # `original_name` is frozen when an entity is first registered,
                # so strip it here too or an existing box keeps reading "_lan2"
                # until its entities are re-created.
                label = label.lstrip("_")
                # Slot names are deliberately NOT the unique_id `kind`. The
                # kind `poe_power` is the CONTROL switch, while the API dict's
                # `poe_power` field means "currently delivering" -- the same
                # word for opposite things, two files apart, which is this
                # repo's recurring bug. Name the slots for what they hold.
                slot_key = {
                    "link": "link",
                    "poe": "poe_sensor",       # binary_sensor: is it delivering
                    "poe_power": "poe_switch",  # switch: may it deliver
                }[kind]
                slot = ports.setdefault(index, {"index": index, "label": label})
                slot[slot_key] = ent.entity_id
                if kind == "link":
                    # The link entity's label wins: a unit with no PoE never
                    # registers a PoE entity, so link is the one always present.
                    slot["label"] = label

        dev_copy = dict(dev)
        if role_map:
            dev_copy["network_entities"] = role_map
        if ports:
            dev_copy["network_ports"] = [ports[i] for i in sorted(ports)]
        enriched.append(dev_copy)
    return enriched


def _classify_heater_entity(domain: str, name: str, entity_id: str) -> str | None:
    """Map one ESPHome heater entity to a `sensa-autoterm-heater-card` role key by
    keyword on its friendly name + platform.

    Ordered so compound names resolve before their substrings ("power level" →
    `power_level`, not `power`; "target temperature" stays a setpoint, not the
    current reading). Returns None for entities the card doesn't surface. The
    caller already drops diagnostic/config-category entities, so the ESP's own
    "ESP Temperature" / "WiFi Signal" never reach here to be mis-read as the
    cabin temperature (the same own-vs-foreign trap the env chips hit).
    """
    n = (name or "").lower()
    if not n:
        n = entity_id.split(".", 1)[-1].replace("_", " ")
    if domain == "select":
        return "mode" if "mode" in n else None
    if domain == "switch":
        if (
            "power" in n
            or "heater" in n
            or "on/off" in n
            or n.strip() in ("on", "enable", "enabled")
        ):
            return "power"
        return None
    if domain == "number":
        if "level" in n or "power" in n:
            return "power_level"
        if "target" in n or "setpoint" in n or "temp" in n:
            return "target_temperature"
        return None
    if domain in ("sensor", "binary_sensor"):
        # The controller's own verdict on whether Vent may be chosen (the
        # heater has shut down). The cards read it; they never re-derive it.
        if domain == "binary_sensor" and "vent" in n:
            return "vent_available"
        # The Baltica panel's mode ("Hot water" / "Hot water and heating"):
        # the card hides its dial on hot water only.
        if domain == "sensor" and "baltica mode" in n:
            return "baltica_mode"
        # The Baltica's circulation pump as the heater runs it (firmware
        # 1.1.22, status byte [13]): the card's pump icon. Before "pump", which is
        # the fuel pump row.
        if domain == "binary_sensor" and "heating circuit" in n:
            return "heating_circuit"
        # The heater's raw fault code (0 = none); `heater_faults.py` logs it.
        if domain == "sensor" and "fault" in n:
            return "fault_code"
        # The Air's glow plug CURRENT (amps), not the glow plug state row.
        if domain == "sensor" and "glow" in n and "current" in n:
            return "glow_current"
        if "glow" in n:
            return "glow_plug"
        if "flame" in n or "combust" in n:
            return "flame_sensor"
        if "pump" in n:
            return "fuel_pump"
        if "volt" in n:
            return "supply_voltage"
        if domain == "sensor" and ("status" in n or "state" in n or "operating" in n):
            return "run_state"
        # The Air's external probe is a reading for the engineer popup, not
        # the cabin temperature the card shows.
        if domain == "sensor" and ("external" in n or "probe" in n):
            return "external_temperature"
        # A Flow-family heater's own coolant sensor: its own role, or the
        # "panel" preference below takes the panel's room reading instead.
        if domain == "sensor" and "coolant" in n:
            return "coolant_temperature"
        if "temp" in n:
            return "current_temperature"
    return None


def _classify_heater_source_entity(domain: str, name: str) -> str | None:
    """The Autoterm controller's temperature-source entities, which are
    config/diagnostic and so never reach `_classify_heater_entity`. Matched on
    the firmware's entity names (Sensa.Control.Firmware ss-airdh.yaml)."""
    n = (name or "").lower()
    # The Baltica's mode buttons (firmware 1.1.4); the longer name first.
    if domain == "button" and "set hot water and heating" in n:
        return "baltica_set_heating"
    if domain == "button" and "set hot water" in n:
        return "baltica_set_hot_water"
    if domain == "select" and "temperature source" in n:
        return "temp_source_select"
    if domain == "number" and "sensa temperature" in n:
        return "sensa_temperature"
    if domain == "sensor" and "panel temperature" in n:
        return "panel_temperature"
    # The extended diagnostics frame (raw hex) and its read-now button.
    if domain == "sensor" and "diagnostics frame" in n:
        return "diagnostics_frame"
    if domain == "button" and "read diagnostics" in n:
        return "read_diagnostics"
    # The black-box report (0x0B, firmware 1.1.14 / 1.1.7): the button reads
    # every page, the text sensor shows each as "<address> <hex>".
    if domain == "button" and "read report" in n:
        return "read_report"
    # Flow family only (firmware Flow 1.1.9 / Baltica 1.1.16): clears the
    # fault-13 lock-out.
    if domain == "button" and n.strip() == "unlock":
        return "unlock"
    if domain == "button" and "water pump run" in n:
        return "pump_run"
    # Air test buttons (firmware Air D 1.1.9). "fan test stop" before the
    # general "test stop", whose words it contains.
    if domain == "button" and "fan test run" in n:
        return "fan_test_run"
    if domain == "button" and "fan test stop" in n:
        return "fan_test_stop"
    if domain == "button" and "fuel pump test run" in n:
        return "fuel_test_run"
    # The general Stop (0x03) that ends a water pump, fan or fuel pump test.
    if domain == "button" and "test stop" in n:
        return "test_stop"
    if domain == "sensor" and "report frame" in n:
        return "report_frame"
    # What the engineer popup shows beside the diagnostics frame: the raw
    # status frame (decoded in autoterm_diag), the heater's own firmware
    # version and the Air's fan speeds.
    if domain == "sensor" and "status frame" in n:
        return "status_frame"
    # Publishes every status frame for ten minutes: the popup's Live button.
    if domain == "switch" and "live status" in n:
        return "live_status"
    # Max Run Time, all three Autoterm SKUs: Unlimited or 1 to 24 h, then
    # the box switches the heater off. Absent on older firmware, and then the
    # card shows no dropdown.
    if domain == "select" and "max run time" in n:
        return "max_run_time"
    # Frost Protection (Air D 1.1.10, Baltica 1.1.18): the frost temperature
    # on the heater's Devices row, and the switch SensaClimate holds on while
    # it runs the van (`climate_control.async_push_frost_standby`).
    if domain == "select" and "frost protection" in n:
        return "frost_protection"
    # Air D 1.1.12: the thermostat a frost start sets.
    if domain == "number" and "frost heat to" in n:
        return "frost_target"
    if domain == "switch" and "sensaclimate active" in n:
        return "sensaclimate_active"
    # Baltica 1.1.25: SensaClimate's room heat, the thermostat while
    # SensaClimate runs the van. No such switch = older firmware, and
    # SensaClimate does not drive that Baltica (`climate_control.is_baltica`).
    if domain == "switch" and "sensaclimate heat" in n:
        return "sensaclimate_heat"
    if domain == "sensor" and "heater firmware" in n:
        return "heater_firmware"
    if domain == "sensor" and "fan speed set" in n:
        return "fan_speed_set"
    if domain == "sensor" and "fan speed actual" in n:
        return "fan_speed_actual"
    # The Flow controller's own thermostat (off / on / heating / holding);
    # `heater_faults.py` logs its switching.
    if domain == "sensor" and "thermostat" in n:
        return "thermostat"
    return None


def _attach_heater_entities(
    hass: HomeAssistant,
    devices: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Return a copy of `devices` with a `service_entities` role-map attached to
    every heater row — AIR (Autoterm Air D) and HYDRONIC (Alde, Autoterm
    Baltica) alike.

    The Autoterm Air 4D reaches HA as an ESPHome device (an ESP32 running the
    Autoterm UART component): HA's `esphome` integration creates the
    sensor/number/select/switch entities natively, and this helper matches them
    back to the heater's device row and builds the `{role: entity_id}` map the
    `sensa-autoterm-heater-card` consumes (see dashboard `_HEATER_ROLE_TO_CARD_FIELD`).

    Mirrors `_attach_relay_entities`' ESPHome config-entry matching (by
    hostname/IP), but classifies entities by keyword on their ESPHome friendly
    name rather than the relay's positional `_relay_N` scheme — a heater exposes
    a mixed bag of platforms, not a uniform switch array. Diagnostic/config
    entities (the ESP's own temperature, WiFi signal, uptime) are skipped so
    they can't be mis-read as heater roles. Empty on a freshly-added heater
    (entities not yet registered); the card omits absent sections and the next
    regen fills the map in.
    """
    from .const import HEATER_SERVICE_CLASSES
    from .vendors.service_classes import classify

    def _is_heater(dev: dict[str, Any]) -> bool:
        # BOTH heater service classes. This gated on `air_heater` alone, so a
        # HYDRONIC heater (Alde, Autoterm Baltica) never got a role map — and
        # every surface that reads one silently dropped it: the Home-layout
        # summary skips a heater whose map is empty, so a customer could tick
        # "Show on Home Layout" on a Baltica and see nothing appear. The two
        # families expose the same ESPHome entity vocabulary (power switch,
        # cabin temperature, target temperature, mode, operating state), so the
        # keyword matcher below already handles both.
        return classify(dev) in HEATER_SERVICE_CLASSES

    if not any(_is_heater(d) for d in devices):
        return list(devices)

    try:
        from homeassistant.helpers import entity_registry as er
    except ImportError:
        _LOGGER.warning("_attach_heater_entities: entity_registry import failed — skipping")
        return list(devices)
    try:
        ent_reg = er.async_get(hass)
    except Exception:
        _LOGGER.warning("_attach_heater_entities: er.async_get failed — skipping", exc_info=True)
        return list(devices)

    enriched: list[dict[str, Any]] = []
    for dev in devices:
        if not _is_heater(dev):
            enriched.append(dev)
            continue

        ip = dev.get("ip_address") or ""
        hostname = dev.get("linked_hostname") or dev.get("hostname") or ""

        # Candidate ESPHome config entries for this heater, by hostname/IP —
        # same precedence as the relay matcher (native hostname entry first,
        # Sensa-created IP entry last).
        candidate_ids: list[str] = []
        for esphome_entry in hass.config_entries.async_entries("esphome"):
            host = (esphome_entry.data or {}).get("host", "")
            device_name = (esphome_entry.data or {}).get("device_name", "")
            if hostname and host in (hostname, f"{hostname}.local"):
                candidate_ids.insert(0, esphome_entry.entry_id)
            elif hostname and device_name == hostname or host and host == ip:
                candidate_ids.append(esphome_entry.entry_id)

        role_map: dict[str, str] = {}
        # Multiple temp sensors are possible (panel + external probe); prefer
        # one whose name reads as the cabin/current reading, else take the first.
        temp_candidates: list[tuple[int, str]] = []
        if candidate_ids:
            cand_set = set(candidate_ids)
            for ent in ent_reg.entities.values():
                if ent.config_entry_id not in cand_set:
                    continue
                if ent.disabled_by is not None:
                    continue
                domain = ent.entity_id.split(".", 1)[0]
                name = ent.original_name or ent.name or ""
                if getattr(ent, "entity_category", None) is not None:
                    # Diagnostic/config: not a heater control or reading, bar
                    # the three the temperature-source bridge drives by name.
                    role = _classify_heater_source_entity(domain, name)
                    if role is not None:
                        role_map.setdefault(role, ent.entity_id)
                    continue
                role = _classify_heater_entity(domain, name, ent.entity_id)
                if role is None:
                    continue
                if role == "current_temperature":
                    n = name.lower()
                    prio = 0 if any(
                        k in n for k in ("current", "cabin", "room", "inside", "air", "panel")
                    ) else 1
                    temp_candidates.append((prio, ent.entity_id))
                    continue
                role_map.setdefault(role, ent.entity_id)
            if temp_candidates:
                temp_candidates.sort(key=lambda x: x[0])
                role_map.setdefault("current_temperature", temp_candidates[0][1])

        dev_copy = dict(dev)
        if role_map:
            dev_copy["service_entities"] = role_map
        enriched.append(dev_copy)
    return enriched


def _esphome_candidate_entry_ids(
    hass: HomeAssistant, dev: dict[str, Any],
) -> list[str]:
    """ESPHome config-entry ids that match a device row by hostname/IP.

    Native hostname entry first, Sensa-created IP entry last (the precedence the
    ESPHome role-map attach helpers rely on). Extracted from the copy-pasted loop
    in `_attach_air_conditioner_entities` / `_attach_heater_entities` /
    `_attach_levelling_entities` / `_attach_relay_entities` (code-review finding
    [5]) so the AC path reuses it rather than adding another copy.
    """
    ip = dev.get("ip_address") or ""
    hostname = dev.get("linked_hostname") or dev.get("hostname") or ""
    candidate_ids: list[str] = []
    for esphome_entry in hass.config_entries.async_entries("esphome"):
        host = (esphome_entry.data or {}).get("host", "")
        device_name = (esphome_entry.data or {}).get("device_name", "")
        if hostname and host in (hostname, f"{hostname}.local"):
            candidate_ids.insert(0, esphome_entry.entry_id)
        elif hostname and device_name == hostname or host and host == ip:
            candidate_ids.append(esphome_entry.entry_id)
    return candidate_ids


def _is_esphome_air_conditioner(dev: dict[str, Any]) -> bool:
    """True for an AC row that reaches HA via an ESPHome bridge (the Dometic
    FreshJet), as opposed to the Velit (its own BLE-GATT vendor integration,
    which pins its OWN climate id). Shared by `_attach_air_conditioner_entities`
    (climate role-map) and `sensor._pairing_controls_for_device` (Pair/Forget
    surface) so both agree on which rows are ESPHome ACs.
    """
    from .vendors.service_classes import classify

    service_class = dev.get("service_class") or classify(dev)
    # `integration_type` OR `integration` — device rows carry either.
    integration = dev.get("integration_type") or dev.get("integration") or ""
    return service_class == "air_conditioner" and integration == "esphome"


def _attach_air_conditioner_entities(
    hass: HomeAssistant,
    devices: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Return a copy of `devices` with a `service_entities` role-map attached to
    every air-conditioner row that reaches HA as an ESPHome device.

    The Dometic FreshJet reaches HA via a Sensa ESP32 BLE bridge running an
    ESPHome component that exposes a single native `climate.*` entity. Unlike the
    Velit (a Sensa-owned BLE-GATT vendor integration that builds its OWN climate
    entity in climate.py), the FreshJet's entity is owned by HA's `esphome`
    integration — so we just match it back to the device row and stamp
    `service_entities = {"climate": <native climate.* id>}`, which the AC card
    (`dashboard._build_air_conditioner_card`) resolves via `_device_role_map`.

    Simpler than `_attach_heater_entities`: an AC exposes ONE climate entity, so
    there's no keyword classifier — we take the single `climate`-domain entity on
    the matched ESPHome config entry. Only rows whose service class is
    `air_conditioner` AND whose integration is `esphome` are touched, so the
    Velit (integration `sensa_velit_rooftop_ac`, its own pinned climate id) is
    left untouched and keeps using its pin. Empty on a freshly-added FreshJet
    (entity not registered yet) — the card OMITS the AC until the AC
    entity-registration listener + rebuild re-run fill the map on the next regen.
    """
    _is_esphome_ac = _is_esphome_air_conditioner

    if not any(_is_esphome_ac(d) for d in devices):
        return list(devices)

    try:
        from homeassistant.helpers import entity_registry as er
    except ImportError:
        _LOGGER.warning(
            "_attach_air_conditioner_entities: entity_registry import failed — skipping"
        )
        return list(devices)
    try:
        ent_reg = er.async_get(hass)
    except Exception:
        _LOGGER.warning(
            "_attach_air_conditioner_entities: er.async_get failed — skipping",
            exc_info=True,
        )
        return list(devices)

    enriched: list[dict[str, Any]] = []
    for dev in devices:
        if not _is_esphome_ac(dev):
            enriched.append(dev)
            continue

        # Candidate ESPHome config entries for this AC, by hostname/IP (shared
        # matcher — see _esphome_candidate_entry_ids).
        candidate_ids = _esphome_candidate_entry_ids(hass, dev)

        climate_entity_id: str | None = None
        light_ids: dict[str, str] = {}
        if candidate_ids:
            cand_set = set(candidate_ids)
            for ent in ent_reg.entities.values():
                if ent.config_entry_id not in cand_set:
                    continue
                if getattr(ent, "entity_category", None) is not None:
                    continue  # diagnostic/config — not the AC control
                if ent.disabled_by is not None:
                    continue
                domain = ent.entity_id.split(".", 1)[0]
                if domain == "climate":
                    if climate_entity_id is None:
                        climate_entity_id = ent.entity_id
                elif domain == "light":
                    # The FreshJet bridge also exposes the unit's interior and
                    # roof lights as native light entities. Both are created
                    # on every unit, and a unit without the hardware simply
                    # reports the light off, so this only names them; the
                    # card decides per render whether each is worth a button.
                    role = _classify_ac_light_entity(ent)
                    if role and role not in light_ids:
                        light_ids[role] = ent.entity_id

        dev_copy = dict(dev)
        if climate_entity_id:
            dev_copy["service_entities"] = {"climate": climate_entity_id, **light_ids}
        enriched.append(dev_copy)
    return enriched


def _classify_ac_light_entity(ent: Any) -> str | None:
    """Map one of an ESPHome-bridged AC's `light.*` entities to its role key
    by keyword on its friendly name (falling back to the entity id).

    The FreshJet bridge names them "Interior Light" and "Roof Light"
    (`ss-domfj-c008.yaml`); the upstream component calls the second one
    "exterior", so both spellings resolve. Anything else is not an AC light
    and is left alone.
    """
    name = str(
        getattr(ent, "original_name", None)
        or getattr(ent, "name", None)
        or ent.entity_id.split(".", 1)[-1].replace("_", " ")
    ).lower()
    if "interior" in name or "cabin" in name:
        return "interior_light"
    if "roof" in name or "exterior" in name or "outdoor" in name:
        return "exterior_light"
    return None


def _classify_levelling_entity(domain: str, name: str, entity_id: str) -> str | None:
    """Map one ESPHome van-level entity to a `levelling_entities` role key by
    keyword on its friendly name + platform.

    The Pro 10 firmware (Sensa.Control.Firmware) exposes pitch / roll / heading
    template sensors, BMP280 temperature + pressure, raw accel x/y/z, a
    "Levelling Mode" switch (fast/slow publish rate) and a "Debug Logging"
    switch. The caller already drops diagnostic/config entities (ESP's own
    Wi-Fi signal, uptime, the four `Sensa Systems` text_sensors), so this only
    sees the customer-facing sensor surface.
    """
    n = (name or "").lower()
    if not n:
        n = entity_id.split(".", 1)[-1].replace("_", " ")
    if domain == "switch":
        if "level" in n and "mode" in n:
            return "mode_switch"
        if "debug" in n:
            return "debug_switch"
        return None
    if domain == "sensor":
        # Match "Acceleration X/Y/Z" before "x"/"y"/"z" appear in other
        # names. Two-word compound to avoid catching a stray axis letter.
        if "accel" in n:
            if " x" in n or n.endswith("x"):
                return "accel_x"
            if " y" in n or n.endswith("y"):
                return "accel_y"
            if " z" in n or n.endswith("z"):
                return "accel_z"
            return None
        if "pitch" in n:
            return "pitch"
        if "roll" in n:
            return "roll"
        if "heading" in n or "compass" in n:
            return "heading"
        if "pressure" in n:
            return "pressure"
        if "temp" in n:
            return "temperature"
    return None


def _attach_levelling_entities(
    hass: HomeAssistant,
    devices: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Return a copy of `devices` with a `levelling_entities` role-map attached
    to every van-level row.

    Mirrors `_attach_heater_entities`' ESPHome config-entry matching (by
    hostname/IP), but classifies entities by keyword for the van-level set:
    pitch / roll / heading / temperature / pressure / accel x|y|z / mode_switch
    / debug_switch. Diagnostic / config entities are skipped so the ESP's own
    Wi-Fi signal and the four "Sensa Systems" text_sensors don't pollute the
    map. Empty on a freshly-added device (entities not yet registered); the
    Settings → Levelling tab omits absent rows and the next regen fills it in.
    """
    from .vendors.service_classes import classify

    def _is_levelling(dev: dict[str, Any]) -> bool:
        return classify(dev) == "levelling"

    if not any(_is_levelling(d) for d in devices):
        return list(devices)

    try:
        from homeassistant.helpers import entity_registry as er
    except ImportError:
        _LOGGER.warning(
            "_attach_levelling_entities: entity_registry import failed — skipping"
        )
        return list(devices)
    try:
        ent_reg = er.async_get(hass)
    except Exception:
        _LOGGER.warning(
            "_attach_levelling_entities: er.async_get failed — skipping",
            exc_info=True,
        )
        return list(devices)

    enriched: list[dict[str, Any]] = []
    for dev in devices:
        if not _is_levelling(dev):
            enriched.append(dev)
            continue

        ip = dev.get("ip_address") or ""
        hostname = dev.get("linked_hostname") or dev.get("hostname") or ""

        candidate_ids: list[str] = []
        for esphome_entry in hass.config_entries.async_entries("esphome"):
            host = (esphome_entry.data or {}).get("host", "")
            device_name = (esphome_entry.data or {}).get("device_name", "")
            if hostname and host in (hostname, f"{hostname}.local"):
                candidate_ids.insert(0, esphome_entry.entry_id)
            elif hostname and device_name == hostname or host and host == ip:
                candidate_ids.append(esphome_entry.entry_id)

        role_map: dict[str, str] = {}
        if candidate_ids:
            cand_set = set(candidate_ids)
            for ent in ent_reg.entities.values():
                if ent.config_entry_id not in cand_set:
                    continue
                if getattr(ent, "entity_category", None) is not None:
                    continue
                if ent.disabled_by is not None:
                    continue
                domain = ent.entity_id.split(".", 1)[0]
                name = ent.original_name or ent.name or ""
                role = _classify_levelling_entity(domain, name, ent.entity_id)
                if role is None:
                    continue
                role_map.setdefault(role, ent.entity_id)

        dev_copy = dict(dev)
        if role_map:
            dev_copy["levelling_entities"] = role_map
        enriched.append(dev_copy)
    return enriched


def _role_map_from_marker(ent_reg: Any, marker: str) -> dict[str, str]:
    """Return {key: entity_id} for every registry entity whose unique_id
    starts with `marker`. `key` is the unique_id remainder after the
    marker — for Sensa-owned vendor entities that remainder is the stable
    `SensorEntityDescription.key`, so it doubles as the role slug."""
    role_map: dict[str, str] = {}
    for ent in ent_reg.entities.values():
        uid = ent.unique_id or ""
        if not uid.startswith(marker):
            continue
        key = uid[len(marker):]
        if key:
            role_map.setdefault(key, ent.entity_id)
    return role_map


def _victron_cerbo_entity_maps(
    ent_reg: Any, entry_id: str, cerbo_id: str,
) -> tuple[dict[str, str], dict[tuple[str, str], dict[str, str]]]:
    """Split a Cerbo's registry entities into the system-aggregate map and
    per-sub-device maps.

    `VictronSensor` system aggregates have unique_ids
    `{entry_id}_victron_cerbo_{cerbo_id}_{key}`; `VictronDeviceSensor`
    per-sub-device entities have
    `{entry_id}_victron_cerbo_{cerbo_id}_{service}_{instance}_{key}`. The
    `{service}_{instance}_` infix (a known Venus service name followed by a
    numeric instance) is what tells the two apart.

    Returns `(system_map, {(service, instance): role_map})`.
    """
    import re

    from .vendors.service_classes import VENUS_SERVICE_TO_SERVICE_CLASS

    prefix = f"{entry_id}_victron_cerbo_{cerbo_id}_"
    services = "|".join(re.escape(s) for s in VENUS_SERVICE_TO_SERVICE_CLASS)
    sub_re = re.compile(rf"^({services})_(\d+)_(.+)$")

    system_map: dict[str, str] = {}
    subdevice_maps: dict[tuple[str, str], dict[str, str]] = {}
    for ent in ent_reg.entities.values():
        uid = ent.unique_id or ""
        if not uid.startswith(prefix):
            continue
        rest = uid[len(prefix):]
        match = sub_re.match(rest)
        if match:
            service, instance, key = match.group(1), match.group(2), match.group(3)
            subdevice_maps.setdefault((service, instance), {})[key] = ent.entity_id
        else:
            system_map.setdefault(rest, ent.entity_id)
    return system_map, subdevice_maps


def _victron_subdevice_name(
    dev_reg: Any, cerbo_id: str, service: str, instance: str,
) -> str:
    """Resolve a Cerbo sub-device's display name from the HA device
    registry (the customer's VictronConnect `CustomName`, written into the
    device card by `VictronDeviceSensor.device_info`), falling back to the
    `<Service Label> #<instance>` default."""
    from .vendors.victron_mqtt_services import SERVICE_LABELS

    try:
        device = dev_reg.async_get_device(
            identifiers={
                (DOMAIN, f"victron_cerbo_{cerbo_id}_{service}_{instance}")
            },
        )
    except Exception:  # noqa: BLE001
        device = None
    if device is not None:
        name = device.name_by_user or device.name
        if name:
            return str(name)
    label = SERVICE_LABELS.get(service, service.title())
    return f"{label} #{instance}"


# Cerbo `battery`-service role keys → Sensa BMS-card role vocabulary.
# A Venus `com.victronenergy.battery` service carries keys derived from
# the VenusSensorDescription.key values (`soc`, `voltage`, …); the native
# `custom:sensa-bms-card` expects the leisure-battery vocabulary
# (`state_of_charge`, `pack_voltage`, …). Per-cell keys (`cell_N_voltage`)
# already match and pass straight through.
_VICTRON_BATTERY_BMS_ROLE_REMAP: dict[str, str] = {
    "soc": "state_of_charge",
    "state_of_health": "state_of_health",
    "voltage": "pack_voltage",
    "current": "pack_current",
    "power": "pack_power",
    "temperature": "battery_temp_1",
    "balancing": "balancing",
}


def _managed_battery_bms_map(role_map: dict[str, str]) -> dict[str, str] | None:
    """Return a `bms_entities` role map for a *managed* Cerbo battery
    (a Victron Smart Lithium reporting per-cell voltages), or None for a
    plain SmartShunt monitor.

    The presence of any `cell_N_voltage` key is the discriminator: only a
    managed BMS battery publishes per-cell voltages over the Cerbo, so a
    SmartShunt (cells absent) returns None and keeps its `battery_monitor`
    classification + `service_entities` map. A managed battery is remapped
    into the BMS-card vocabulary so `_build_bms_card` can render it.
    """
    import re

    cell_re = re.compile(r"cell_\d+_voltage")
    if not any(cell_re.fullmatch(k) for k in role_map):
        return None
    out: dict[str, str] = {}
    for key, eid in role_map.items():
        if cell_re.fullmatch(key):
            out[key] = eid
        elif key in _VICTRON_BATTERY_BMS_ROLE_REMAP:
            out[_VICTRON_BATTERY_BMS_ROLE_REMAP[key]] = eid
    return out


def _attach_service_class_rows(
    hass: HomeAssistant,
    entry_id: str,
    devices: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Apply the service-class abstraction to the device list.

    For every row:
      * stamp a canonical `service_class` via `classify()` (vendor-neutral
        — catalog `type`, Venus service name and integration slug all
        normalise to the same vocabulary).

    Plus, for Victron:
      * the Cerbo gateway row gets a `victron_system_entities` role-map
        (the system aggregates the power-flow card consumes);
      * one synthetic row is appended per Cerbo sub-device
        `(service, instance)` pair found in the entity registry, each with
        its own `service_class` + `service_entities` role-map and a
        `display_name` resolved from the HA device registry;
      * the Sensa-owned Orion XS row gets a `service_entities` role-map.

    Generalises `_attach_bms_entity_prefixes` / `_attach_network_entity_prefixes`
    — those still run, so the BMS and Network views keep their existing
    `bms_entities` / `network_entities` maps. Cerbo sub-devices are not
    backend devices (they fan out dynamically over MQTT), so they only
    appear here once their entities reach the registry;
    `_on_new_victron_device` fires `SIGNAL_DASHBOARD_REGEN_REQUESTED` so a
    newly-appeared sub-device triggers a regen and lands on the Electrical
    view within one keepalive cycle.
    """
    from .vendors.service_classes import (
        VENUS_SERVICE_TO_SERVICE_CLASS,
        classify,
    )

    try:
        from homeassistant.helpers import device_registry as dr
        from homeassistant.helpers import entity_registry as er
    except ImportError:
        return list(devices)
    try:
        ent_reg = er.async_get(hass)
        dev_reg = dr.async_get(hass)
    except Exception:  # noqa: BLE001
        return list(devices)

    enriched: list[dict[str, Any]] = []
    cerbo_ids: list[str] = []
    for dev in devices:
        dev_copy = dict(dev)
        service_class = classify(dev_copy)
        if service_class:
            dev_copy["service_class"] = service_class

        integration = (
            dev_copy.get("integration_type") or dev_copy.get("integration") or ""
        )
        device_id = dev_copy.get("device_id")

        if integration == "sensa_victron_mqtt" and device_id:
            cerbo_ids.append(device_id)
            system_map, _ = _victron_cerbo_entity_maps(
                ent_reg, entry_id, device_id,
            )
            if system_map:
                dev_copy["victron_system_entities"] = system_map
            # NB: the Remote Console card's host is resolved at card-build
            # time by `dashboard._victron_coordinator_host`, NOT enriched
            # here — this enrichment runs during `async_setup_entry` before
            # `_async_start_vendor_integrations` creates the coordinator, so
            # a lookup here always misses it.
        elif integration == "sensa_victron_orion_xs" and device_id:
            role_map = _role_map_from_marker(
                ent_reg, f"{entry_id}_victron_orion_xs_{device_id}_",
            )
            if role_map:
                dev_copy["service_entities"] = role_map
        elif integration == "sensa_dji_ble" and device_id:
            role_map = _role_map_from_marker(
                ent_reg, f"{entry_id}_dji_power_{device_id}_",
            )
            if role_map:
                dev_copy["service_entities"] = role_map
        elif integration == "sensa_tpms_ble" and device_id:
            role_map = _role_map_from_marker(
                ent_reg, f"{entry_id}_tpms_ble_{device_id}_",
            )
            if role_map:
                dev_copy["service_entities"] = role_map
        elif integration == "mopeka" and device_id:
            from . import mopeka

            role_map = mopeka.role_map(hass, entry_id, dev_copy)
            if role_map:
                dev_copy["service_entities"] = role_map
            fluid = mopeka.fluid_type(
                hass, mopeka.device_mac(dev_copy),
                hass.config_entries.async_get_entry(entry_id), device_id,
            )
            if fluid:
                # A Mopeka has no fluid-type entity: its medium lives on the
                # native config entry, so the dials read it from the row.
                dev_copy["tank_fluid_type"] = fluid

        enriched.append(dev_copy)

    # Synthetic rows for every Cerbo sub-device the registry knows about.
    # Appended after the real rows so the existing views (which filter by
    # integration slug) are unaffected.
    for cerbo_id in cerbo_ids:
        _system_map, subdevice_maps = _victron_cerbo_entity_maps(
            ent_reg, entry_id, cerbo_id,
        )
        for (service, instance), role_map in sorted(subdevice_maps.items()):
            service_class = VENUS_SERVICE_TO_SERVICE_CLASS.get(service)
            if not service_class:
                continue
            # Managed-lithium override. Venus reports a Victron Smart
            # Lithium on the same `battery` service as a SmartShunt, but a
            # managed BMS battery also publishes per-cell voltages. When
            # cells are present, reclassify the row from `battery_monitor`
            # to `battery` (leisure) and attach a BMS-card role map so it
            # renders on the Habitation BMS tab alongside Roamer/Fogstar.
            # A SmartShunt (no cells) is unchanged.
            bms_map: dict[str, str] | None = None
            if service == "battery":
                bms_map = _managed_battery_bms_map(role_map)
                if bms_map:
                    service_class = "battery"
            # Position-based override for grid meters. Venus OS uses the
            # same `com.victronenergy.grid` service for shore-input
            # meters AND meters wired on the Multiplus's AC-Out-2 line —
            # the `Position` field disambiguates (0=AC input 1, 1=AC
            # output, 2=AC input 2). When the customer has wired an
            # output meter to expose AC-Out-2 load separately, classify
            # it under `ac_output_meter` so the power-flow card's
            # `shore_ac_load` slot can find it. No Position entity yet
            # (e.g. coordinator hasn't seen the topic) → leave as a
            # plain `grid_meter`; the next regen picks it up once
            # Position arrives.
            if service == "grid":
                position_eid = role_map.get("position")
                if position_eid:
                    state_obj = hass.states.get(position_eid)
                    raw = state_obj.state if state_obj else None
                    try:
                        position = int(float(raw)) if raw not in (None, "unknown", "unavailable") else None
                    except (TypeError, ValueError):
                        position = None
                    if position == 1:
                        service_class = "ac_output_meter"
            sub_row: dict[str, Any] = {
                "device_id": f"{cerbo_id}:{service}:{instance}",
                "integration_type": "service_class_device",
                "service_class": service_class,
                "victron_service": service,
                "victron_instance": instance,
                "victron_cerbo_id": cerbo_id,
                "display_name": _victron_subdevice_name(
                    dev_reg, cerbo_id, service, instance,
                ),
                "service_entities": role_map,
                # Default product image for the synthetic sub-device row
                # so the power-flow card can show "here's the thing
                # supplying this slot" without needing a separate catalog
                # entry per Cerbo sub-device. Brand-specific (Victron)
                # because by definition a Cerbo's MQTT fanout is Victron
                # hardware. Non-Victron equivalents (Renogy DC-DC,
                # Battle Born BMS, …) come through their own discovery
                # paths and carry their own catalog `image`.
                "image": _VICTRON_VENUS_SERVICE_IMAGE.get(service),
            }
            # A managed Smart Lithium gets a BMS-card role map (cells +
            # remapped pack/SoC/SoH/balancing) on top of the raw
            # `service_entities` so both the BMS card and the power-flow
            # fallback can resolve it.
            if bms_map:
                sub_row["bms_entities"] = bms_map
                sub_row["image"] = "victron-smartlithium.webp"
            enriched.append(sub_row)
    return enriched


# Default product images for Cerbo MQTT sub-devices. The fanout is
# Victron-only by construction so brand-locking these is honest, not a
# vendor assumption. Services without an entry stay imageless and the
# card falls back to its MDI icon for those slots.
#
# Filenames point at variant-specific assets that ACTUALLY EXIST in
# webcards/assets/images/ — the obvious-looking generic names
# (victron-smartshunt.webp etc.) are 404s, a long-standing inconsistency
# between the catalog and the shipped assets. Picking a sensible
# default variant (the most common modern SKU) is the pragmatic fix
# until real generic images get added to the asset folder.
_VICTRON_VENUS_SERVICE_IMAGE: dict[str, str] = {
    "battery": "victron-smartshunt-500a.webp",
    "solarcharger": "victron-smartsolar-100-50.webp",
    "alternator": "victron-orion-xs-12-12-50.webp",
    "dcdc": "victron-orion-xs-12-12-50.webp",
}


def _attach_power_relays(devices: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Attach `power_relay` (an ESPHome relay switch entity_id) to any device a
    relay channel has been assigned to as an Integrated Device.

    A relay channel assigned `device:<id>` via the "Device Type" dropdown means
    "this channel switches power to that device", so the linked device's card
    can render a Power on/off control (Phase 3 of the relay routing feature —
    `sensa-router-card` renders it today; other device cards can read the same
    `power_relay` key as they grow the control).

    Reads the relay rows enriched by `_attach_relay_entities`
    (`relay_assignments` / `relay_entities` / `relay_enabled`); only ENABLED
    channels with a resolved ESPHome relay entity contribute, so this MUST run
    after `_attach_relay_entities`. Last assignment wins if two channels target
    the same device (a misconfiguration, not expected).
    """
    power_map: dict[str, str] = {}
    for device in devices:
        if not is_relay_device(device):
            continue
        assignments = device.get("relay_assignments") or {}
        relay_entities = device.get("relay_entities") or {}
        relay_enabled = device.get("relay_enabled") or {}
        for slot, assignment in assignments.items():
            if not isinstance(assignment, str) or not assignment.startswith("device:"):
                continue
            if relay_enabled.get(slot) is False:  # disabled channel
                continue
            relay_eid = relay_entities.get(slot)
            if not relay_eid:  # ESPHome relay not connected yet
                continue
            target_id = assignment[len("device:"):]
            if target_id:
                power_map[target_id] = relay_eid

    if not power_map:
        return devices

    enriched: list[dict[str, Any]] = []
    for device in devices:
        d_id = str(device.get("device_id") or device.get("id") or "")
        if d_id and d_id in power_map:
            device = {**device, "power_relay": power_map[d_id]}
        enriched.append(device)
    return enriched


def _host_of_url(url: str) -> str:
    """`http://192.168.2.15:80/x` -> `192.168.2.15`. Exact, so `.1` never
    matches `.15` the way a substring test would."""
    return url.split("://", 1)[-1].split("/", 1)[0].split(":", 1)[0]


async def _async_adopt_shelly(hass: Any, device: dict[str, Any]) -> None:
    """Create HA's own `shelly` config entry for a Shelly Sensa just added.

    Sensa finds a Shelly with its own `/shelly` sweep because HA's zeroconf
    cannot see across the IoT VLAN, so there is usually no pending flow to
    accept. In order:

      1. an entry already exists for this MAC or host: nothing to do;
      2. HA did see it (a flat network) and holds a discovery flow at
         `confirm_discovery`: confirm it;
      3. otherwise run the user flow by hand: pick "manual" on the device
         picker HA shows when it has discovered anything, then give the host.

    A no-auth Gen2+ Shelly creates its entry straight from the host step
    (read off HA 2026.8.3's shelly config_flow). Anything else that comes back
    (a credentials form, an error) is logged with its step and errors and the
    flow is aborted, so it neither passes silently nor sits in HA's
    Discovered list for a customer who cannot open HA.
    """
    from homeassistant.config_entries import SOURCE_USER

    ip = device.get("ip_address") or ""
    label = device.get("display_name") or ip or "Shelly"
    if _shelly_entry_ids(hass, device):
        _LOGGER.info("Shelly adopt: %s already has a shelly entry", label)
        return
    if not ip:
        _LOGGER.warning("Shelly adopt: %s has no address, cannot adopt", label)
        return
    mac = _canon_id(device.get("mac_address") or "")
    flows = hass.config_entries.flow

    try:
        for flow in flows.async_progress_by_handler("shelly", include_uninitialized=True):
            if flow.get("step_id") != "confirm_discovery":
                continue
            ctx = flow.get("context") or {}
            uid = _canon_id(ctx.get("unique_id") or "")
            flow_host = _host_of_url(str(ctx.get("configuration_url") or ""))
            if (mac and uid == mac) or flow_host == ip:
                result = await flows.async_configure(flow["flow_id"], user_input={})
                _LOGGER.info(
                    "Shelly adopt: confirmed HA's discovery flow for %s (%s)",
                    label, result.get("type"),
                )
                return

        result = await flows.async_init("shelly", context={"source": SOURCE_USER})
        if result.get("type") == "form" and result.get("step_id") == "user":
            result = await flows.async_configure(
                result["flow_id"], user_input={"device": "manual"},
            )
        if result.get("type") == "form" and result.get("step_id") == "user_manual":
            result = await flows.async_configure(
                result["flow_id"],
                user_input={"host": ip, "port": 80, "verify_ssl": False},
            )
    except Exception:
        _LOGGER.warning("Shelly adopt: %s at %s failed", label, ip, exc_info=True)
        return

    kind = str(result.get("type") or "")
    if kind == "create_entry":
        _LOGGER.info("Shelly adopt: created the shelly entry for %s at %s", label, ip)
        return
    _LOGGER.warning(
        "Shelly adopt: %s at %s did not create an entry (type=%s step=%s "
        "reason=%s errors=%s)",
        label, ip, kind, result.get("step_id"), result.get("reason"),
        result.get("errors"),
    )
    if kind == "form" and result.get("flow_id"):
        try:
            flows.async_abort(result["flow_id"])
        except Exception:  # noqa: BLE001, S110
            pass


async def _async_adopt_smlight(hass: Any, device: dict[str, Any]) -> None:
    """Create HA's own `smlight` config entry for an SLZB Sensa just added.

    The `_async_adopt_shelly` shape, for the same reason: HA's zeroconf cannot
    see across the IoT VLAN, so there is usually no pending flow to accept. On a
    flat network HA holds one at `confirm_discovery`, so that is confirmed; else
    the user flow takes the host and creates the entry straight away (read off
    HA 2026.8.3's smlight config_flow). An SLZB with web login on comes back as
    an `auth` form, which is logged and aborted. Zigbee itself does not need
    this entry; it carries the diagnostics and firmware updates.
    """
    from homeassistant.config_entries import SOURCE_USER

    ip = device.get("ip_address") or ""
    label = device.get("display_name") or ip or "SMLight SLZB"
    mac = _canon_id(device.get("mac_address") or "")
    for existing in hass.config_entries.async_entries("smlight"):
        if (mac and _canon_id(existing.unique_id or "") == mac) or (
            ip and (existing.data or {}).get("host") == ip
        ):
            _LOGGER.info("SMLight adopt: %s already has an smlight entry", label)
            return
    if not ip:
        _LOGGER.warning("SMLight adopt: %s has no address, cannot adopt", label)
        return
    flows = hass.config_entries.flow

    try:
        for flow in flows.async_progress_by_handler("smlight", include_uninitialized=True):
            if flow.get("step_id") != "confirm_discovery":
                continue
            if mac and _canon_id((flow.get("context") or {}).get("unique_id") or "") == mac:
                result = await flows.async_configure(flow["flow_id"], user_input={})
                _LOGGER.info(
                    "SMLight adopt: confirmed HA's discovery flow for %s (%s)",
                    label, result.get("type"),
                )
                return

        result = await flows.async_init("smlight", context={"source": SOURCE_USER})
        if result.get("type") == "form" and result.get("step_id") == "user":
            result = await flows.async_configure(
                result["flow_id"], user_input={"host": ip},
            )
    except Exception:
        _LOGGER.warning("SMLight adopt: %s at %s failed", label, ip, exc_info=True)
        return

    kind = str(result.get("type") or "")
    if kind == "create_entry":
        _LOGGER.info("SMLight adopt: created the smlight entry for %s at %s", label, ip)
        return
    _LOGGER.warning(
        "SMLight adopt: %s at %s did not create an entry (type=%s step=%s "
        "reason=%s errors=%s)",
        label, ip, kind, result.get("step_id"), result.get("reason"),
        result.get("errors"),
    )
    if kind == "form" and result.get("flow_id"):
        try:
            flows.async_abort(result["flow_id"])
        except Exception:  # noqa: BLE001, S110
            pass


def _shelly_relay_entities(
    hass: HomeAssistant, ent_reg: Any, device: dict[str, Any],
) -> dict[str, str]:
    """Resolve `relay_N` slot -> `switch.*` entity_id for an adopted Shelly.

    A Shelly is the Adopt method: HA's own `shelly` integration owns the
    entities and names them `switch.<device_name>` / `switch.<device_name>_2`,
    never `switch.<prefix>_relay_N`, so the ESPHome grouping in
    `_attach_relay_entities` finds nothing for one.

    Channel order comes from the UNIQUE_ID (`<mac>-switch:0`, `<mac>-switch:1`),
    never the entity_id. The entity_id carries the customer's device name and
    changes when the vendor's firmware renames a component; the unique_id
    cannot change without HA treating it as a different entity. Keying on the
    name is how a card silently ends up driving a different relay after a
    firmware update, which on a 4-channel unit means the awning button
    switching the fridge.

    Falls back to stable-sorted entity_id order when no unique_id carries a
    channel index, and logs when it does, because that fallback is a guess.
    """
    import re as _re

    entry_ids = _shelly_entry_ids(hass, device)
    if not entry_ids:
        return {}

    switches = [
        ent for ent in ent_reg.entities.values()
        if ent.config_entry_id in entry_ids
        and ent.entity_id.startswith("switch.")
    ]
    if not switches:
        return {}

    indexed: list[tuple[int, str]] = []
    for ent in switches:
        match = _re.search(r"switch:(\d+)", str(getattr(ent, "unique_id", "") or ""))
        if match:
            indexed.append((int(match.group(1)), ent.entity_id))
    if indexed:
        # Shelly numbers its channels from 0; Sensa slots are 1-based.
        return {
            f"relay_{idx + 1}": eid
            for idx, eid in sorted(indexed, key=lambda pair: pair[0])
        }

    _LOGGER.warning(
        "Shelly relay %s: no switch unique_id carried a channel index, "
        "falling back to entity_id order. Channel numbering is a GUESS and a "
        "firmware rename can reorder it; confirm which output each channel "
        "drives before relying on it.",
        device.get("device_id") or device.get("id") or "unknown",
    )
    return {
        f"relay_{n}": eid
        for n, eid in enumerate(sorted(ent.entity_id for ent in switches), start=1)
    }


def _attach_relay_rows_guarded(
    hass: HomeAssistant,
    devices: list[dict[str, Any]],
    entry: ConfigEntry | None = None,
) -> list[dict[str, Any]]:
    """`_attach_relay_entities` then `_attach_power_relays`, never raising.

    Both setup and the rebuild call this BEFORE `set_dashboard_devices(...,
    hass)`. A raise here used to skip that call, so the generator ran with no
    `hass`, read the install flavour as the BYO default, and a Container
    appliance lost its System tab, gained the dev Cards tab and rendered an
    empty Habitation (1.4.8, a Shelly). On failure the relay rows go through
    unenriched, so the box loses its Switches cards, not its dashboards.
    """
    try:
        devices = _attach_relay_entities(hass, devices, entry)
    except Exception:
        _LOGGER.warning("relay entity attach failed", exc_info=True)
    try:
        devices = _attach_power_relays(devices)
    except Exception:
        _LOGGER.warning("power relay attach failed", exc_info=True)
    return devices


def _attach_relay_entities(
    hass: HomeAssistant,
    devices: list[dict[str, Any]],
    entry: ConfigEntry | None = None,
) -> list[dict[str, Any]]:
    """Return a copy of `devices` with `relay_entities` and `relay_labels` maps
    attached to every relay row.

    `relay_entities`: slot key → entity_id (from HA entity registry).
    `relay_labels`: slot key → display label (custom name or "Relay N" default).

    If `entry` is provided, stored labels from entry.options["relay_labels"] are
    applied to the HA entity registry so friendly names propagate everywhere.
    Empty on first install (entities not yet registered); `_build_relay_card`
    omits the entities block gracefully and the next regen fills it in.
    """
    try:
        from homeassistant.helpers import entity_registry as er
    except ImportError:
        _LOGGER.warning("_attach_relay_entities: entity_registry import failed — skipping")
        return list(devices)
    try:
        ent_reg = er.async_get(hass)
    except Exception:
        _LOGGER.warning("_attach_relay_entities: er.async_get failed — skipping", exc_info=True)
        return list(devices)

    # Scan the whole entity registry once. Group switch.*_relay_N entities
    # by their prefix (everything before _relay_N) — each prefix is one
    # ESPHome device. Also build a map from entity_id → registry entry so
    # we can check config_entry_id without a second pass.
    relay_groups: dict[str, dict[str, str]] = {}  # prefix → {relay_N: entity_id}
    eid_to_entry: dict[str, Any] = {}

    def _relay_eid_rank(ent_obj: Any) -> int:
        """Higher = more likely the LIVE channel switch (vs an orphaned
        duplicate left behind by a delete/re-add). Prefers an entity whose
        config entry still exists and whose state isn't unavailable, so a
        drifted `_relay_3_2` live entity wins over a stale clean `_relay_3`
        orphan (and vice-versa)."""
        rank = 0
        ce_id = getattr(ent_obj, "config_entry_id", None)
        if ce_id and hass.config_entries.async_get_entry(ce_id) is not None:
            rank += 2
        st = hass.states.get(ent_obj.entity_id)
        if st is not None and st.state not in ("unavailable", "unknown"):
            rank += 1
        return rank

    for ent in ent_reg.entities.values():
        eid = ent.entity_id
        eid_to_entry[eid] = ent
        if not eid.startswith("switch.") or "_relay_" not in eid:
            continue
        suffix = eid.rsplit("_relay_", 1)[1]
        # Channel number = the LEADING digits of the suffix. A clean "3" and
        # a collision-drifted "3_2" (left by a delete/re-add orphan) both
        # resolve to channel 3 — the old code required the WHOLE suffix to be
        # digits, so `_relay_3_2` was dropped and the channel vanished from
        # the card (only the 2 un-drifted channels survived). Tolerate the
        # tail here; pick the live entity per channel below.
        digits = ""
        for ch in suffix:
            if ch.isdigit():
                digits += ch
            else:
                break
        if not digits:
            continue
        prefix = eid.rsplit("_relay_", 1)[0]
        slot = f"relay_{digits}"
        group = relay_groups.setdefault(prefix, {})
        existing = group.get(slot)
        if existing is None or _relay_eid_rank(ent) > _relay_eid_rank(eid_to_entry[existing]):
            group[slot] = eid

    relay_device_count = sum(
        1 for d in devices
        if is_relay_device(d)
    )

    enriched: list[dict[str, Any]] = []
    for dev in devices:
        if not is_relay_device(dev):
            enriched.append(dev)
            continue

        ip = dev.get("ip_address") or ""
        hostname = dev.get("linked_hostname") or dev.get("hostname") or ""

        relay_map: dict[str, str] = {}
        # `relay_N` -> that circuit's live power sensor. Only a metered relay
        # (a Shelly Pro 4PM) has one; it drives `sensa-switches-card`.
        relay_power_map: dict[str, str] = {}

        # An adopted Shelly has no ESPHome entry and no `_relay_N` naming, so
        # the ESPHome strategies below can never match one. Resolve it from
        # its own config entry first; the rest of the row (labels, enabled,
        # assignments) is built exactly as it is for an ESPHome relay.
        if (dev.get("integration_type") or dev.get("integration") or "") == "shelly":
            relay_map = _shelly_relay_entities(hass, ent_reg, dev)
            relay_power_map = shelly_channel_power_entities(hass, ent_reg, dev)

        # Build a prioritised list of candidate ESPHome config entries for
        # this relay device.  Lower number = higher preference.
        #   0 — hostname-exact match (native HA-discovered entry)
        #   1 — device_name match (also native)
        #   2 — IP-exact match (Sensa-created entry — least preferred because
        #         it may duplicate a native entry and have stale/unavailable
        #         entities when the device is already connected elsewhere)
        candidate_entries: list[tuple[int, str]] = []
        for esphome_entry in hass.config_entries.async_entries("esphome"):
            host = (esphome_entry.data or {}).get("host", "")
            device_name = (esphome_entry.data or {}).get("device_name", "")
            if host == ip:
                candidate_entries.append((2, esphome_entry.entry_id))
            elif hostname and host in (hostname, f"{hostname}.local"):
                candidate_entries.append((0, esphome_entry.entry_id))
            elif hostname and device_name == hostname:
                candidate_entries.append((1, esphome_entry.entry_id))
        candidate_entries.sort(key=lambda x: x[0])

        # Strategy 1: match relay group via config_entry_id, preferring
        # native (hostname-based) entries over Sensa-created (IP-based) ones.
        for _prio, entry_id in ([] if relay_map else candidate_entries):
            for group in relay_groups.values():
                sample_eid = next(iter(group.values()))
                sample_ent = eid_to_entry.get(sample_eid)
                if sample_ent and sample_ent.config_entry_id == entry_id:
                    relay_map = group
                    break
            if relay_map:
                break

        # Strategy 2: Strategy 1 found nothing (entry not yet set up, or
        # entity not yet registered).  For a single relay device pick the
        # best available group: prefer groups whose config entry still exists
        # and is hostname-based (native) over IP-based (Sensa-created).
        # Orphaned groups (config entry deleted) are skipped.
        if not relay_map and relay_device_count == 1 and relay_groups:
            best_group: dict[str, str] | None = None
            best_prio = 999
            for group in relay_groups.values():
                sample_eid = next(iter(group.values()))
                sample_ent = eid_to_entry.get(sample_eid)
                if not sample_ent:
                    continue
                ce_id = sample_ent.config_entry_id
                if ce_id is None:
                    grp_prio = 3
                else:
                    ce = hass.config_entries.async_get_entry(ce_id)
                    if ce is None:
                        continue  # orphaned group
                    ce_host = (ce.data or {}).get("host", "")
                    if hostname and ce_host in (hostname, f"{hostname}.local"):
                        grp_prio = 0
                    elif ce_host == ip:
                        grp_prio = 2
                    else:
                        grp_prio = 1
                if best_group is None or grp_prio < best_prio:
                    best_group = group
                    best_prio = grp_prio
            if best_group is not None:
                relay_map = best_group

        dev_copy = dict(dev)
        device_id_str = str(dev.get("device_id") or dev.get("id") or "unknown")

        # Channel-name (text) and channel-enabled (switch) entity IDs.
        # Primary lookup: query the registry by unique_id — handles users
        # with pre-existing entries whose entity_ids don't match the new
        # deterministic scheme. Fallback: deterministic ID from const.py
        # (matches the value text.py / switch.py set on self.entity_id
        # for fresh entries). Always populated for every relay device so
        # the Settings card renders Channel names + Channels enabled
        # sections regardless of ESPHome connection state.
        from .const import (
            relay_channel_assignment_entity_id,
            relay_channel_enabled_entity_id,
            relay_channel_image_entity_id,
            relay_channel_name_entity_id,
            relay_device_name_entity_id,
        )
        relay_name_entities: dict[str, str] = {}
        relay_enabled_entities: dict[str, str] = {}
        relay_assignment_entities: dict[str, str] = {}
        relay_image_entities: dict[str, str] = {}
        relay_enabled: dict[str, bool] = {}
        relay_assignments: dict[str, str] = {}
        relay_images: dict[str, str] = {}
        stored_enabled = (
            (entry.options.get("relay_enabled") if entry else None) or {}
        ).get(device_id_str, {})
        stored_assignments = (
            (entry.options.get("relay_assignments") if entry else None) or {}
        ).get(device_id_str, {})
        stored_images = (
            (entry.options.get("relay_images") if entry else None) or {}
        ).get(device_id_str, {})
        nomad_entry_id = entry.entry_id if entry else None
        # Device-level name text (one per relay device). Same primary
        # lookup pattern as the channel name texts: query the registry
        # by unique_id, fall back to the deterministic id if unknown.
        device_name_uid = (
            f"{nomad_entry_id}_{device_id_str}_relay_device_name"
            if nomad_entry_id else None
        )
        relay_device_name_entity = (
            (device_name_uid and ent_reg.async_get_entity_id("text", DOMAIN, device_name_uid))
            or relay_device_name_entity_id(device_id_str)
        )
        for n in range(1, 9):
            slot = f"relay_{n}"
            relay_enabled[slot] = stored_enabled.get(slot) is not False
            relay_assignments[slot] = stored_assignments.get(slot, "unassigned")
            relay_images[slot] = stored_images.get(slot, "")
            text_uid = f"{nomad_entry_id}_{device_id_str}_relay_{n}_name" if nomad_entry_id else None
            switch_uid = f"{nomad_entry_id}_{device_id_str}_relay_{n}_enabled" if nomad_entry_id else None
            assign_uid = f"{nomad_entry_id}_{device_id_str}_relay_{n}_assignment" if nomad_entry_id else None
            image_uid = f"{nomad_entry_id}_{device_id_str}_relay_{n}_image" if nomad_entry_id else None
            relay_name_entities[slot] = (
                (text_uid and ent_reg.async_get_entity_id("text", DOMAIN, text_uid))
                or relay_channel_name_entity_id(device_id_str, n)
            )
            relay_enabled_entities[slot] = (
                (switch_uid and ent_reg.async_get_entity_id("switch", DOMAIN, switch_uid))
                or relay_channel_enabled_entity_id(device_id_str, n)
            )
            relay_assignment_entities[slot] = (
                (assign_uid and ent_reg.async_get_entity_id("select", DOMAIN, assign_uid))
                or relay_channel_assignment_entity_id(device_id_str, n)
            )
            relay_image_entities[slot] = (
                (image_uid and ent_reg.async_get_entity_id("text", DOMAIN, image_uid))
                or relay_channel_image_entity_id(device_id_str, n)
            )
        dev_copy["relay_name_entities"] = relay_name_entities
        dev_copy["relay_enabled_entities"] = relay_enabled_entities
        dev_copy["relay_assignment_entities"] = relay_assignment_entities
        dev_copy["relay_image_entities"] = relay_image_entities
        dev_copy["relay_enabled"] = relay_enabled
        dev_copy["relay_assignments"] = relay_assignments
        dev_copy["relay_images"] = relay_images
        dev_copy["relay_device_name_entity"] = relay_device_name_entity
        if relay_power_map:
            dev_copy["relay_power_entities"] = relay_power_map

        if relay_map:
            dev_copy["relay_entities"] = relay_map

            # Resolve display labels and apply any stored custom names to the
            # HA entity registry so they propagate to automations/scripts/UI.
            stored_labels: dict[str, str] = {}
            if entry is not None:
                stored_labels = dict(
                    (entry.options.get("relay_labels") or {}).get(device_id_str) or {}
                )

            relay_labels: dict[str, str] = {}
            for slot_key, entity_id in relay_map.items():
                n = slot_key.split("_")[1]
                custom = stored_labels.get(slot_key, "").strip()
                existing_entry = ent_reg.async_get(entity_id)
                if custom:
                    if existing_entry and existing_entry.name != custom:
                        try:
                            ent_reg.async_update_entity(entity_id, name=custom)
                        except Exception:
                            _LOGGER.debug(
                                "_attach_relay_entities: failed to rename %r to %r",
                                entity_id, custom, exc_info=True,
                            )
                    relay_labels[slot_key] = custom
                else:
                    # Clear any lingering override so entity reverts to default name
                    if existing_entry and existing_entry.name is not None:
                        try:
                            ent_reg.async_update_entity(entity_id, name=None)
                        except Exception:
                            _LOGGER.debug(
                                "_attach_relay_entities: failed to clear name on %r",
                                entity_id, exc_info=True,
                            )
                    relay_labels[slot_key] = f"Relay {n}"

            dev_copy["relay_labels"] = relay_labels

        enriched.append(dev_copy)
    return enriched


async def _async_rebuild_sensa_dashboards(
    hass: HomeAssistant, entry: ConfigEntry
) -> None:
    """Rebuild the Nomad Settings dashboard YAML from the current backend
    device list. Called after any add_devices / remove_devices invocation so
    per-category views (Network, Bluetooth, …) pick up the change without
    needing a config-flow re-run."""
    from .dashboard import (
        async_create_or_update_sensa_settings_dashboard,
        set_dashboard_devices,
    )

    backend_url = entry.data.get(CONF_BACKEND_URL)
    if not backend_url:
        return
    client = SensaApiClient(hass, backend_url)
    try:
        devices_resp = await client.async_get_devices()
    except Exception:
        _LOGGER.warning(
            "dashboard rebuild: could not fetch backend devices",
            exc_info=True,
        )
        return

    raw_devices = devices_resp.get("devices", [])

    # Late-arriving devices (backend slow on HA restart so the
    # platform-setup pass saw an empty device list, then the regen
    # signal fires once data is back) need their relay platform
    # entities created NOW. Without this the dashboard YAML below
    # references entity_ids that were never registered, and the
    # toggles render against missing entities. Mirrors the relay
    # loop in async_setup_entry — same dynamic-add path, just gated
    # by the registry-existence check inside the helper so we never
    # re-add an existing device's switches.
    for device in raw_devices:
        if is_relay_device(device):
            try:
                await _async_add_relay_platform_entities(hass, entry, device)
            except Exception:
                _LOGGER.warning(
                    "dashboard rebuild: relay platform entity creation "
                    "failed for %s",
                    device.get("device_id"), exc_info=True,
                )
        if (
            device.get("service_class") == "levelling"
            or device_kind(device) == "van_level"
        ):
            try:
                await _async_add_levelling_platform_entities(hass, entry, device)
            except Exception:
                _LOGGER.warning(
                    "dashboard rebuild: levelling platform entity creation "
                    "failed for %s",
                    device.get("device_id"), exc_info=True,
                )
        # No kind gate here: `_async_add_home_placement_selects` classifies the
        # device itself and no-ops for anything with no Home Layout control, so
        # heaters, lights AND ACs all flow through. (This loop runs on RAW
        # devices before `_attach_service_class_rows` stamps `service_class`,
        # hence the re-classify inside — a literal-field check would miss them.)
        try:
            await _async_add_home_placement_selects(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: Home Layout select creation failed for %s",
                device.get("device_id"), exc_info=True,
            )
        # "Temperature Sensor Source" on an Autoterm Air heater; no-ops for
        # anything whose controller lacks the source firmware.
        try:
            await _async_add_heater_temp_source_select(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: heater temperature source select creation "
                "failed for %s",
                device.get("device_id"), exc_info=True,
            )
        # A Sensa Fan Temperature Control's autopilot settings; no-ops for anything else.
        try:
            await _async_add_fan_autopilot_entities(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: fan autopilot entity creation failed for %s",
                device.get("device_id"), exc_info=True,
            )
        # A Sensa DC Meter's circuit names; no-ops for anything else.
        try:
            await _async_add_dc_meter_entities(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: DC meter entity creation failed for %s",
                device.get("device_id"), exc_info=True,
            )
        # A Mopeka's Bottle Size select and % Tank Level; no-ops for anything else.
        try:
            await _async_add_mopeka_entities(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: Mopeka entity creation failed for %s",
                device.get("device_id"), exc_info=True,
            )
        # An Autoterm heater's diesel sensors; no-ops for anything else.
        try:
            await _async_add_diesel_entities(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: diesel sensor creation failed for %s",
                device.get("device_id"), exc_info=True,
            )
        # Same deal for the "Show Power In Header" toggle — it classifies the
        # device itself and no-ops for anything ineligible, so no gate here.
        try:
            await _async_add_header_power_chip_switch(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: header power-chip switch creation failed "
                "for %s",
                device.get("device_id"), exc_info=True,
            )
        # And the "Show Temperature In Header" toggle, same self-classifying
        # no-gate rule.
        try:
            await _async_add_header_temp_chip_switch(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: header temp-chip switch creation failed "
                "for %s",
                device.get("device_id"), exc_info=True,
            )
        # And the "Header Short Name" field, offered wherever either chip is.
        try:
            await _async_add_header_short_name_text(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: header short-name field creation failed "
                "for %s",
                device.get("device_id"), exc_info=True,
            )
        # And the Temperature Watch / Fridge / Freezer toggles, same
        # self-classifying no-gate rule.
        try:
            await _async_add_temperature_watch_switch(hass, entry, device)
        except Exception:
            _LOGGER.warning(
                "dashboard rebuild: temperature-watch switch creation failed "
                "for %s",
                device.get("device_id"), exc_info=True,
            )

    devices_list = _attach_bms_entity_prefixes(
        hass, entry.entry_id, raw_devices,
    )
    devices_list = _attach_network_entity_prefixes(
        hass, entry.entry_id, devices_list,
    )
    devices_list = _attach_heater_entities(hass, devices_list)
    devices_list = _attach_air_conditioner_entities(hass, devices_list)
    devices_list = _attach_levelling_entities(hass, devices_list)
    devices_list = _attach_relay_rows_guarded(hass, devices_list, entry)
    devices_list = _attach_service_class_rows(
        hass, entry.entry_id, devices_list,
    )
    _stamp_home_layout_flags(devices_list, entry)
    set_dashboard_devices(devices_list, hass)
    _async_compute_and_broadcast_eligibility(hass, entry, devices_list)
    try:
        await async_create_or_update_sensa_settings_dashboard(hass)
    except Exception:
        _LOGGER.warning(
            "dashboard rebuild: YAML generation failed",
            exc_info=True,
        )

    # Refresh the panels so their conditional tabs (BMS / Network /
    # Engine) track the same device changes the Lovelace dashboards just
    # regenerated for: re-register (fixes the config for the next page
    # load) AND fire the bus event so any OPEN panel live-refreshes via
    # its WS subscription without a reload. Must be hass.bus.async_fire
    # (reaches the browser), not a dispatcher signal (in-process only).
    await _async_register_panels(hass)
    hass.bus.async_fire(EVENT_PANEL_CONFIG_CHANGED)


async def _async_backfill_native_model(
    hass: HomeAssistant,
    client: SensaApiClient,
    sensa_device_id: str,
    domain: str,
    mac: str,
) -> None:
    """Read back the model name HA's native integration set on the
    just-created device, push it into the Sensa backend.

    The native integration (victron_ble in particular) sets
    `device_info.model` on its first decrypted advert. That happens
    after `flow.async_configure(... create_entry)` returns, so we
    can't read it inline. Poll the device registry on a 2 s tick for
    up to ~60 s (covers slow proxies + slow first decrypt). When we
    see a non-empty model, write it to our backend so `_pick_image`
    can swap the generic image for a model-specific one and the
    customer sees "Victron SmartShunt 500A" instead of "Victron
    SmartShunt" on dashboards.

    Identifier-matching strategy: native integrations vary in how
    they key device_registry entries. We match on `(domain, X)` for
    every X in {colonised MAC upper, no-colon MAC upper, no-colon
    MAC lower}. First match wins.
    """
    if not (sensa_device_id and domain and mac):
        return
    try:
        from homeassistant.helpers.device_registry import (
            async_get as _dr_async_get,
        )
    except ImportError:
        return

    hex_mac = mac.replace(":", "").replace("-", "").upper()
    if len(hex_mac) != 12:
        _LOGGER.debug(
            "backfill_native_model: skipping bad MAC %r for sensa "
            "device %s",
            mac, sensa_device_id,
        )
        return
    colon_upper = ":".join(hex_mac[i:i + 2] for i in range(0, 12, 2))
    candidates = {
        (domain, colon_upper),
        (domain, hex_mac),
        (domain, hex_mac.lower()),
    }

    deadline = asyncio.get_event_loop().time() + 60.0
    last_logged_model: str = ""
    while asyncio.get_event_loop().time() < deadline:
        try:
            registry = _dr_async_get(hass)
        except Exception:
            _LOGGER.debug(
                "backfill_native_model: device_registry lookup raised",
                exc_info=True,
            )
            return
        device = None
        for ident in candidates:
            device = registry.async_get_device(identifiers={ident})
            if device is not None:
                break
        if device is None:
            await asyncio.sleep(2.0)
            continue
        model = (device.model or "").strip()
        if not model:
            # Device exists but native integration hasn't filled in
            # the model yet. Keep waiting.
            await asyncio.sleep(2.0)
            continue
        if model == last_logged_model:
            await asyncio.sleep(2.0)
            continue
        last_logged_model = model
        try:
            await client.async_update_device(
                device_id=sensa_device_id,
                model=model,
            )
            _LOGGER.info(
                "backfill_native_model: %s = %r (read from %s device "
                "registry)",
                sensa_device_id, model, domain,
            )
            return
        except Exception:
            _LOGGER.debug(
                "backfill_native_model: backend update_device failed "
                "for %s",
                sensa_device_id, exc_info=True,
            )
            return
    _LOGGER.debug(
        "backfill_native_model: %s (%s/%s) — no model from %s after "
        "60 s, giving up",
        sensa_device_id, domain, mac, domain,
    )


def _async_retitle_native_entry(
    hass: HomeAssistant,
    domain: str,
    mac: str,
    new_title: str,
) -> None:
    """Rename a freshly-created native HA config entry to a friendly title.

    Some native bluetooth integrations (victron_ble is the motivating
    case) set their entry title from the cached advertisement's `name`
    attribute. When the cached advert packet didn't carry a `local_name`
    — common for Victron devices which only include the name in a
    subset of their manufacturer-data packets — the title collapses to
    the MAC address. Customer sees `C6:D0:EA:4D:AC:CC` on the device
    card instead of `BP-SmartShunt500`. Our picker knows a better name
    because the Discovery sensor captured it from a different source
    (the raw BLE advert). Use that after the flow completes.

    Safe to call with any MAC format (colon or no-colon, any case) —
    we normalise both sides before comparing.
    """
    if not (domain and mac and new_title):
        return
    mac_norm = mac.replace(":", "").upper()
    try:
        entries = hass.config_entries.async_entries(domain)
    except Exception:  # noqa: BLE001
        return
    for entry in entries:
        uid = (entry.unique_id or "").replace(":", "").upper()
        if uid != mac_norm:
            continue
        if (entry.title or "") == new_title:
            return
        try:
            hass.config_entries.async_update_entry(entry, title=new_title)
            _LOGGER.info(
                "Retitled %s entry %s: %r -> %r",
                domain, entry.entry_id, entry.title, new_title,
            )
        except Exception:
            _LOGGER.debug(
                "Retitle of %s entry %s to %r failed",
                domain, entry.entry_id, new_title, exc_info=True,
            )
        return


def _native_domain_for_integration(integration_type: str) -> str | None:
    """Return the native HA domain for a cooperate integration, or None.

    Sensa-owned integrations (sensa_bms_ble, sensa_teltonika_api, etc.) have no
    native HA entry to clean up — only cooperate ones (ruuvitag_ble, smlight)
    do. Source of truth: the BLE_NATIVE_PROFILES list + the cooperate section of
    the device catalog.
    """
    from .config_flow import BLE_NATIVE_PROFILES
    from .device_catalog import PHYSICAL_DEVICE_CATALOG

    # `_native_cooperate_domains` reads the same two sources; change both together.
    for profile in BLE_NATIVE_PROFILES:
        if profile.get("integration") == integration_type and profile.get("domain"):
            return profile["domain"]
    for catalog in PHYSICAL_DEVICE_CATALOG:
        if catalog.get("integration") == integration_type and catalog.get("accept_native"):
            return catalog["accept_native"]
    return None


def _ble_profile_matches(
    profile: dict[str, Any],
    manufacturer_id: str,
    name: str,
    device_subtype: str = "",
    service_uuids: list[str] | None = None,
) -> bool:
    """Check a BLE advertisement row against a profile's match criteria.

    Matching rules:

      - `manufacturer_id` must match (case-insensitive). Required —
        every profile declares one.
      - `name_prefix` and `device_subtype` are alternative tie-breakers.
        If the profile declares either, the row must satisfy AT LEAST
        ONE. Without this, multi-profile domains (victron_ble covers
        SmartShunt, SmartSolar, Orion XS, Cerbo) route every row to
        whichever profile is listed first in BLE_NATIVE_PROFILES — e.g.
        an Orion XS add would get dispatched to the SmartShunt flow
        and stall on the wrong step sequence.
      - `name_prefix` may be a string or a list of strings (matched
        via startswith). `device_subtype` is compared as a case-
        sensitive exact string (stamped by `_annotate_victron_subtype`
        / BMS classifier / Ruuvi classifier etc.).
    """
    # Service-UUID-gated profiles (e.g. the Velit AC: service 0xFFE0, no
    # manufacturer data) match on the advertised service UUID instead of a
    # manufacturer_id. 0xFFE0 is a generic UART service, so the name_prefix
    # tie-breaker below still has to match.
    profile_service_uuid = profile.get("service_uuid")
    if profile_service_uuid:
        row_uuids = {str(u).lower() for u in (service_uuids or [])}
        if str(profile_service_uuid).lower() not in row_uuids:
            return False
    else:
        profile_mfg = profile.get("manufacturer_id")
        if profile_mfg is not None:
            if isinstance(profile_mfg, int):
                expected = f"0x{profile_mfg:04X}"
            else:
                expected = str(profile_mfg)
            if manufacturer_id.upper() != expected.upper():
                return False

    profile_prefix = profile.get("name_prefix")
    profile_subtype = str(profile.get("device_subtype") or "")

    # Neither declared → mfr_id alone is the gate, accept.
    if not profile_prefix and not profile_subtype:
        return True

    # Accept on ANY declared selector matching.
    if profile_prefix:
        prefixes = (
            [profile_prefix] if isinstance(profile_prefix, str)
            else list(profile_prefix)
        )
        if any(name.startswith(p) for p in prefixes):
            return True
    return bool(profile_subtype) and device_subtype == profile_subtype


async def async_unload_entry(hass: HomeAssistant, entry: ConfigEntry) -> bool:
    """Unload a config entry.

    Cleanly stops every vendor coordinator before clearing the runtime
    dict. Previously the dict was cleared but coordinator background
    tasks (MQTT subscribers, BLE advert listeners, gRPC pollers) kept
    running against their cached references — on reload a new coordinator
    would start alongside the old one, and for the Cerbo MQTT client
    that produced client-id collisions with the Venus OS broker kicking
    connections every ~2 s in a reconnect loop.
    """
    unload_ok = await hass.config_entries.async_unload_platforms(entry, PLATFORMS)

    if unload_ok:
        # Stop the customer alert engine's evaluation timer. It's a run-level
        # singleton; clearing the flag too means a reload (unload → setup)
        # re-creates it cleanly. (A genuine remove leaves it stopped.)
        alerts_cancel = hass.data.get(DOMAIN, {}).pop(_ALERTS_CANCEL, None)
        if alerts_cancel:
            try:
                alerts_cancel()
            except Exception:
                _LOGGER.debug("async_unload_entry: alerts cancel raised", exc_info=True)
            hass.data.get(DOMAIN, {}).pop(_ALERTS_STARTED, None)

        # Stop the Schengen sampler timers (run-level singletons, like the
        # alert engine). A reload re-creates them via _async_start_schengen_sampler.
        for _key in (
            _SCHENGEN_SAMPLE_CANCEL,
            _SCHENGEN_STATE_CANCEL,
            _ALARMS_TICK_CANCEL,
            _CRYPTO_AUTOPILOT_CANCEL,
            _TRACKING_SAMPLE_CANCEL,
            _TRACKING_UPLOAD_CANCEL,
            _TRACKING_STATE_CANCEL,
            _TRACKING_STATE_FIRST_CANCEL,
            _MOVEMENT_SAMPLE_CANCEL,
        ):
            _cancel = hass.data.get(DOMAIN, {}).pop(_key, None)
            if _cancel:
                try:
                    _cancel()
                except Exception:
                    _LOGGER.debug(
                        "async_unload_entry: %s cancel raised", _key, exc_info=True,
                    )

        # Drop the Sensa panels so a disabled/unloaded integration
        # doesn't leave dead sidebar entries pointing at a module that
        # no longer loads. A reload re-registers them in setup.
        try:
            from homeassistant.components import frontend

            from .dashboard import PANELS
            for p in PANELS:
                frontend.async_remove_panel(
                    hass, p["path"], warn_if_unknown=False,
                )
        except Exception:
            _LOGGER.debug("Sensa panel removal on unload failed", exc_info=True)

        runtime = hass.data[DOMAIN].pop(entry.entry_id, None)
        if runtime:
            cancel = runtime.pop("web_cards_cancel", None)
            if cancel:
                cancel()
            # Stop the boot-race deployment_mode watch if it's still re-checking
            # (it self-cancels after a confirmed reading / max attempts, but a
            # reload mid-window must not leave it firing against a dead entry).
            im_watch_cancel = runtime.pop("deployment_mode_watch_cancel", None)
            if im_watch_cancel:
                im_watch_cancel()
            # Stop the network-status poller (runs every 60s) so it doesn't
            # keep firing against a torn-down entry after unload/reload.
            net_cancel = runtime.pop("network_poll_cancel", None)
            if net_cancel:
                net_cancel()
            usage_cancel = runtime.pop("data_usage_poll_cancel", None)
            if usage_cancel:
                usage_cancel()
            # Stop the self-rescheduling system-resources poller (async_call_later
            # returns a cancel callback; may be None if the prime hadn't armed).
            sysres_cancel = runtime.pop("system_resources_poll_cancel", None)
            if sysres_cancel:
                sysres_cancel()
            # Stop the self-rescheduling app-usage poller (async_call_later
            # returns a cancel callback; may be None if the prime hadn't armed).
            appusage_cancel = runtime.pop("app_usage_poll_cancel", None)
            if appusage_cancel:
                appusage_cancel()
            # Stop the self-rescheduling Pi hardware poller (Sensa Core sensors).
            hardware_cancel = runtime.pop("system_hardware_poll_cancel", None)
            if hardware_cancel:
                hardware_cancel()
            # Stop the self-rescheduling containers poller (Supervisor panel).
            containers_cancel = runtime.pop("containers_poll_cancel", None)
            if containers_cancel:
                containers_cancel()
            # Cancel any pending post-action container refreshes (admin.py schedules
            # a 7s + 16s shot after a start/stop/restart) so they don't fire with a
            # stale client against a reloaded entry.
            for refresh_cancel in runtime.pop("container_action_refresh_cancels", []) or []:
                if refresh_cancel:
                    refresh_cancel()
            # Stop the fast OTA-progress watch (self-rescheduling, container
            # updates only; may be None if a tick was mid-flight).
            ota_watch_cancel = runtime.pop("ota_status_poll_cancel", None)
            if ota_watch_cancel:
                ota_watch_cancel()
            # Same for the fast backup-progress watch, which runs only while a
            # backup is being written. Without this a reload during a backup
            # leaves a timer firing against a dead runtime for up to an hour.
            backup_watch_cancel = runtime.pop("backup_progress_poll_cancel", None)
            if backup_watch_cancel:
                backup_watch_cancel()
            # Stop the boot-time channel-latest re-poll (container only).
            ota_latest_cancel = runtime.pop("ota_latest_prime_cancel", None)
            if ota_latest_cancel:
                ota_latest_cancel()
            # Cancel any pending "Check now" follow-up polls.
            for check_cancel in runtime.pop("ota_check_refresh_cancels", []) or []:
                if check_cancel:
                    check_cancel()
            # Stop the remote-support expiry tick (every 60s) for the same
            # reason — it must not keep firing against a torn-down entry.
            rs_cancel = runtime.pop("remote_support_tick_cancel", None)
            if rs_cancel:
                rs_cancel()
            # Drop the backend-vanish listener so its cleanup callback
            # can't fire mid-teardown (the coordinator pushes one final
            # update during unload and would otherwise see every
            # registered device as "vanished" and try to HA-clean them
            # at the same time as the platform-unload path is running).
            remove_vanish = runtime.pop("_backend_vanish_listener_remove", None)
            if remove_vanish:
                try:
                    remove_vanish()
                except Exception:
                    _LOGGER.debug(
                        "async_unload_entry: vanish listener remove raised",
                        exc_info=True,
                    )
            # Cancel the per-Cerbo Venus OS update-check timers before the
            # coordinators go, or a reload leaves the old timers firing
            # alongside the new ones and the GX gets asked to check for
            # updates once per reload, for ever.
            for _key in [
                k for k in runtime
                if k.startswith("victron_firmware_check_")
            ]:
                _cancel = runtime.pop(_key, None)
                if not _cancel:
                    continue
                try:
                    _cancel()
                except Exception:
                    _LOGGER.debug(
                        "async_unload_entry: %s cancel raised", _key,
                        exc_info=True,
                    )
            coordinators = runtime.get("vendor_coordinators", {})
            for device_id, coord in list(coordinators.items()):
                if hasattr(coord, "async_stop"):
                    try:
                        await coord.async_stop()
                    except Exception:
                        _LOGGER.debug(
                            "async_unload_entry: coordinator %s async_stop raised",
                            device_id, exc_info=True,
                        )
            coordinators.clear()

    return unload_ok


async def async_remove_entry(hass: HomeAssistant, entry: ConfigEntry) -> None:
    """Clean up when the integration is removed.

    Drain each registered device through the same per-device remove
    pipeline `remove_devices` uses — so BLE coordinators shut down,
    native cooperate flows (ruuvitag_ble, govee_ble) get their HA
    entries removed, adopted ESPHome entries are cleaned, and the
    backend registrations are scrubbed one-by-one. Falls back to the
    bulk `clear_devices` endpoint as a belt-and-braces step in case
    any per-device call failed (e.g. add-on restarting mid-delete).

    Four stores to scrub:

    1. Per-device: BLE coordinator shutdown, native HA entries, ESPHome
       adopt entries, Sensa backend device rows.
    2. Bulk backend wipe (`/devices/clear` + `/discoveries/clear`) as a
       safety net — the customer removing the integration expects a
       clean slate.
    3. HA RestoreEntity state for our text/switch config entities
       (passwords, SSL toggle). `async_will_remove_from_hass` on each
       entity scrubs the value before HA persists final state.
    4. HA entity registry entries (done automatically by HA on config
       entry removal — we don't touch it).
    """
    backend_url = entry.data.get(CONF_BACKEND_URL)

    if backend_url:
        client = SensaApiClient(hass, backend_url)

        # Step 1 — per-device teardown. Fetch the current device list and
        # route every one through _async_handle_remove_devices via a
        # synthetic ServiceCall. That gets us the BLE coordinator shutdown,
        # native-flow unload, and ESPHome adopt-cleanup paths without
        # duplicating their logic here.
        try:
            devices_resp = await client.async_get_devices()
            backend_devices = devices_resp.get("devices", []) or []
        except Exception:
            backend_devices = []
            _LOGGER.warning(
                "async_remove_entry: could not fetch backend devices for "
                "per-device teardown — falling straight to bulk clear",
                exc_info=True,
            )

        if backend_devices:
            ids = []
            for dev in backend_devices:
                # Prefer the backend's device_id (stable, unique). Fall back
                # to discovery id or MAC so the remove handler's dispatch
                # can still resolve the device if the device_id shape
                # changed mid-session (e.g. post-rename).
                device_id = (
                    dev.get("device_id")
                    or dev.get("linked_discovery_id")
                    or dev.get("linked_mac_address")
                    or dev.get("mac_address")
                )
                if device_id:
                    ids.append(device_id)

            if ids:
                _LOGGER.info(
                    "async_remove_entry: tearing down %d backend device(s) "
                    "through per-device remove pipeline",
                    len(ids),
                )
                try:
                    fake_call = ServiceCall(
                        hass, DOMAIN, "remove_devices", {"ids": ids},
                    )
                    await _async_handle_remove_devices(hass, entry, fake_call)
                except Exception:
                    _LOGGER.warning(
                        "async_remove_entry: per-device teardown raised — "
                        "continuing to bulk clear",
                        exc_info=True,
                    )

        # Step 2 — belt-and-braces bulk wipe. Even if the per-device path
        # above succeeded we still call this so any rows the teardown
        # couldn't resolve (backend drift, partial state) get cleared.
        try:
            await client.async_clear_devices()
            await client.async_clear_discoveries()
            _LOGGER.info(
                "async_remove_entry: bulk-cleared backend device and "
                "discovery registries"
            )
        except Exception:
            # Loud — not debug. If the add-on is stopped when the user
            # removes the integration, the backend keeps its device list
            # and the next install sees the old devices with old
            # credentials. Customer-facing "I deleted it but my password
            # was remembered" bug.
            _LOGGER.exception(
                "async_remove_entry: failed to bulk-clear Sensa backend — "
                "add-on may be stopped. Device registrations (including "
                "router credentials) may persist to a reinstall. Restart "
                "the Sensa App add-on and remove the integration again "
                "to fully scrub."
            )

    await async_remove_sensa_settings_dashboard(hass)

    # Strip bundled Sensa themes from /config/themes/. Best-effort —
    # an uninstall must complete even if the themes dir is unwritable.
    try:
        from .frontend import async_remove_sensa_themes
        await async_remove_sensa_themes(hass)
    except Exception:
        _LOGGER.debug("Sensa theme removal failed during uninstall", exc_info=True)

    # Remove ignored entries we created for native integrations
    suppressed = entry.data.get("suppressed_integrations", [])
    for domain in suppressed:
        for ignored_entry in hass.config_entries.async_entries(domain):
            if ignored_entry.source == SOURCE_IGNORE:
                await hass.config_entries.async_remove(ignored_entry.entry_id)
                _LOGGER.info("Restored native %s discovery", domain)

    # Unconditionally blank Z2M's serial config. The per-device teardown above
    # *does* clear it when the coordinator is removed, but only via a
    # fire-and-forget `async_create_task` (which can be dropped during a full
    # teardown) AND only when the backend is reachable (no devices fetched ->
    # the per-device loop never runs). Either way the dead serial lingers in
    # Z2M's configuration.yaml after the integration is gone. Awaiting the
    # idempotent helper here (no-ops when the serial is already empty, MQTT is
    # absent, or we're not under Supervisor) makes the cleanup reliable.
    try:
        await _async_clear_zigbee_coordinator_config(hass)
    except Exception:
        _LOGGER.debug(
            "async_remove_entry: Z2M serial clear raised", exc_info=True,
        )
